    ('7a2f12ac-2e56-595a-98fe-6fb66cba49ce'::uuid, 'Quiz — Verne, 1874 — refaire une civilisation à partir de rien', 'Français', '1re', 'L’Île mystérieuse, Jules Verne', 'aa3d924b-9513-5328-87a5-aebbb5d69f4e'::uuid),
    ('5911ef52-49ae-5d4e-945f-b884647d51a5'::uuid, 'Quiz — Corneille, 1636 — le théâtre dans le théâtre dans le théâtre', 'Français', '1re', 'L’Illusion comique, Pierre Corneille', '237e2c97-cc60-521b-b44d-2e1a0b26b7a5'::uuid),
    ('3dabc8f5-d117-579e-afc7-d7409a092845'::uuid, 'Quiz — Gide, 1902 — se guérir, et détruire', 'Français', '1re', 'L’Immoraliste, André Gide', '249cc925-8b88-554f-b09c-a353634845df'::uuid),
    ('2d823806-50df-519b-b739-6a018f91d3b3'::uuid, 'Quiz — Voltaire, 1767 — un Huron en Basse-Bretagne', 'Français', '1re', 'L’Ingénu, Voltaire', '6e6f4523-b20d-53ba-b6af-a61be689d555'::uuid),
    ('18c8e0f2-66b3-5fdf-8659-4a35e7428f33'::uuid, 'Quiz — Zola, 1886 — le peintre qui n’y arrive pas', 'Français', '1re', 'L’Œuvre, Émile Zola', '35398408-b658-587c-837c-bfd47f06c561'::uuid),
    ('2b3b8f40-95d0-5809-b201-15dfe717698a'::uuid, 'Quiz — Villon, vers 1462 — les morts s’adressent aux vivants', 'Français', '1re', 'La Ballade des pendus, François Villon', '219bf1e2-777a-55dd-b639-17650c2c2c61'::uuid),
    ('87ee6326-a438-59fc-ad7f-78781005f636'::uuid, 'Quiz — Zola, 1890 — le train, le meurtre, l’hérédité', 'Français', '1re', 'La Bête humaine, Émile Zola', 'ce54f222-6687-5f15-b237-3b90a6964a3b'::uuid),
    ('5eac1d03-7c9d-5230-b9f3-4fcc354af7c8'::uuid, 'Quiz — Stendhal, 1839 — Waterloo, la prison, le bonheur', 'Français', '1re', 'La Chartreuse de Parme, Stendhal', 'b99041d6-d9cf-51a8-a420-0ebff336b546'::uuid),
    ('3225be99-cfa5-52f4-b4cd-3de075a672f9'::uuid, 'Quiz — Balzac, 1829-1850 — un monde en quatre-vingt-dix romans', 'Français', '1re', 'La Comédie humaine, Honoré de Balzac', '187cd76f-599d-5e52-a2b7-6cd66811cca9'::uuid),
    ('dcf48744-3e57-57ad-87bd-52122168030b'::uuid, 'Quiz — Madame de La Fayette, 1724 — la nouvelle la plus noire', 'Français', '1re', 'La Comtesse de Tende, Madame de La Fayette', '50d6f0ce-96ce-56a5-a76e-820bb51af31b'::uuid),
    ('06db8fe5-dbff-567b-879d-127fb0c89c7f'::uuid, 'Quiz — Malraux, 1933 — Shanghai, 1927', 'Français', '1re', 'La Condition humaine, André Malraux', 'f206364d-2ee6-5068-ba9b-067ba9d027e8'::uuid),
    ('0e36b033-f851-51f7-b6e9-e2b6a968804d'::uuid, 'Quiz — Molière, 1663 — répondre aux critiques par une pièce', 'Français', '1re', 'La Critique de l’École des femmes, Molière', '17d5bfe9-45df-5206-b872-567579b60be5'::uuid),
    ('8178d399-880e-52c9-ab1a-1bf58f9da134'::uuid, 'Quiz — Zola, 1872 — spéculer sur Paris éventré', 'Français', '1re', 'La Curée, Émile Zola', '5f55c63c-0d2f-502d-b3cd-34a200a13348'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('14cd413c-3476-59fc-8646-078bdcb3c8d8'::uuid, 'c3170521-a8ae-567b-b2d9-4a8f2f24b9ca'::uuid, 'Où se déroule le roman ?', 'mcq', '["À Saumur","À Angoulême","À Paris","À Tours"]'::jsonb, 0, 'Il appartient aux Scènes de la vie de province.', 1),
    ('4bdfd0b4-eb4a-5c84-91af-af1d3107455a'::uuid, 'c3170521-a8ae-567b-b2d9-4a8f2f24b9ca'::uuid, 'Comment le père Grandet a-t-il fait fortune ?', 'mcq', '["Ancien tonnelier, il a spéculé sur les terres et les biens nationaux","Par héritage","Dans le commerce colonial","Par un mariage riche"]'::jsonb, 0, 'Il tient sa famille dans l’ignorance de sa richesse.', 2),
    ('85b96935-952e-59a9-882f-c5552ce62bfc'::uuid, 'c3170521-a8ae-567b-b2d9-4a8f2f24b9ca'::uuid, 'Que donne Eugénie à son cousin Charles ?', 'mcq', '["Son or, en secret","La maison familiale","Une lettre de recommandation","Rien"]'::jsonb, 0, 'La découverte de ce don déclenche la séquestration.', 3),
    ('f6bd9045-2c29-54db-97e5-687e37fbf1d8'::uuid, 'c3170521-a8ae-567b-b2d9-4a8f2f24b9ca'::uuid, 'Que fait Charles à son retour ?', 'mcq', '["Il épouse une aristocrate et rompt par lettre","Il épouse Eugénie","Il meurt aux Indes","Il rembourse tout le monde"]'::jsonb, 0, 'La fortune l’a rendu semblable au vieux Grandet.', 4),
    ('ba52106b-53e9-52d5-92cb-46dd95c7cf04'::uuid, 'c3170521-a8ae-567b-b2d9-4a8f2f24b9ca'::uuid, 'Comment finit Eugénie ?', 'mcq', '["Riche, veuve et seule, vivant comme son père","Ruinée","Mariée à Charles","Au couvent"]'::jsonb, 0, 'La victime finit par ressembler à son bourreau.', 5),
    ('c59c651f-ac81-5fb1-b3a3-5b7f1cedfb63'::uuid, 'c3170521-a8ae-567b-b2d9-4a8f2f24b9ca'::uuid, 'L’argent est un simple arrière-plan dans ce roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est un personnage : il structure la maison, la ville, les mariages et jusqu’à la piété.', 6),
    ('8dbfafd8-30b0-50fc-b7fc-81684086dc3d'::uuid, '0dea4182-4087-51a3-8bad-9fac3c17a5b6'::uuid, 'Combien de livres les Fables comptent-elles ?', 'mcq', '["Douze","Six","Vingt","Trois"]'::jsonb, 0, 'Publiés en trois recueils, de 1668 à 1694.', 1),
    ('d7b96e8b-e5c1-5601-89ad-7893c8d94657'::uuid, '0dea4182-4087-51a3-8bad-9fac3c17a5b6'::uuid, 'À quels auteurs La Fontaine emprunte-t-il ses sujets ?', 'mcq', '["Ésope, Phèdre et la tradition orientale","Homère et Virgile","Sénèque et Cicéron","Rabelais et Marot"]'::jsonb, 0, 'Il transforme la matière par le style, pas par l’invention.', 2),
    ('61ee118a-e424-552c-9b33-0ab0633bd031'::uuid, '0dea4182-4087-51a3-8bad-9fac3c17a5b6'::uuid, 'Quelle forme métrique caractérise les Fables ?', 'mcq', '["Le vers libre classique, mélangeant les mètres","L’alexandrin exclusivement","La prose","Le décasyllabe"]'::jsonb, 0, 'Le changement de mètre souligne les chutes.', 3),
    ('fd6a2569-6f74-5d69-abe9-be7647ed7efd'::uuid, '0dea4182-4087-51a3-8bad-9fac3c17a5b6'::uuid, 'Que dénonce « Les Animaux malades de la peste » ?', 'mcq', '["La justice qui condamne le plus faible","La peur des épidémies","L’avarice des marchands","L’ignorance des paysans"]'::jsonb, 0, '« Selon que vous serez puissant ou misérable… »', 4),
    ('46ec7623-73d1-599a-94b9-ea27728583aa'::uuid, '0dea4182-4087-51a3-8bad-9fac3c17a5b6'::uuid, 'Quelle est la formule de La Fontaine sur la morale ?', 'mcq', '["« Une morale nue apporte de l’ennui »","« Il faut châtier les mœurs par le rire »","« Le vrai peut quelquefois n’être pas vraisemblable »","« Rien n’est plus beau que le vrai »"]'::jsonb, 0, 'Le conte fait passer le précepte avec lui.', 5),
    ('296f0f21-5949-5658-8ad5-ef37957b9d08'::uuid, '0dea4182-4087-51a3-8bad-9fac3c17a5b6'::uuid, 'Les Fables ne visent que le jeune public.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sous l’apparence enfantine, elles font la satire de la cour de Louis XIV.', 6),
    ('c78143d5-b7c9-5a65-abf4-9ef6e8356492'::uuid, '271aaac0-d3c7-513f-8340-eee04dad19ca'::uuid, 'Quelle est la situation de Hamm ?', 'mcq', '["Aveugle et paralysé dans un fauteuil à roulettes","Sourd et muet","Enfermé dans une poubelle","Debout, immobile"]'::jsonb, 0, 'Clov, lui, ne peut ni s’asseoir ni partir.', 1),
    ('af2ee579-b99a-54b7-aeed-50b4a54e543f'::uuid, '271aaac0-d3c7-513f-8340-eee04dad19ca'::uuid, 'Où vivent Nagg et Nell ?', 'mcq', '["Dans deux poubelles","Dans la pièce voisine","Au grenier","Dehors"]'::jsonb, 0, 'Ils se souviennent d’un jour heureux au lac de Côme.', 2),
    ('0380db7d-2c1c-5f44-bdfa-4d6814b8c71e'::uuid, '271aaac0-d3c7-513f-8340-eee04dad19ca'::uuid, 'Que voit Clov par la fenêtre ?', 'mcq', '["Rien : « zéro »","La mer agitée","Une ville en ruine","Un jardin"]'::jsonb, 0, 'La fin du monde semble déjà advenue.', 3),
    ('52ff1f87-5efa-54c9-a086-44902164703b'::uuid, '271aaac0-d3c7-513f-8340-eee04dad19ca'::uuid, 'D’où vient le titre de la pièce ?', 'mcq', '["Des échecs : le moment où l’issue est connue mais où il faut jouer","Du théâtre antique","D’un jeu de cartes","D’une expression militaire"]'::jsonb, 0, 'Beckett était un joueur d’échecs passionné.', 4),
    ('96415702-90fe-5424-816b-9385585f6e45'::uuid, '271aaac0-d3c7-513f-8340-eee04dad19ca'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Clov reste sur le seuil, Hamm se couvre le visage","Clov part définitivement","Hamm meurt","Les parents sortent des poubelles"]'::jsonb, 0, 'Le départ annoncé n’a pas lieu : c’est la structure même de Beckett.', 5),
    ('5c079f83-02cc-589b-852e-1fca6038b432'::uuid, '271aaac0-d3c7-513f-8340-eee04dad19ca'::uuid, 'La pièce est dépourvue d’humour.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’humour noir y est constant : « Rien n’est plus drôle que le malheur. »', 6),
    ('60a79461-04d6-5688-a66a-fdbdc74536d1'::uuid, '8f0387f2-f980-5d29-86c2-2a5c926f1c8c'::uuid, 'Sous quel pseudonyme Rabelais publie-t-il ?', 'mcq', '["Alcofribas Nasier","Maître Janotus","Ponocrates","Grandgousier"]'::jsonb, 0, 'Une anagramme de François Rabelais.', 1),
    ('e6f3b12e-6264-59e0-8d2f-4d8979a408dc'::uuid, '8f0387f2-f980-5d29-86c2-2a5c926f1c8c'::uuid, 'Que signifie la « substantifique moelle » ?', 'mcq', '["Le sens profond caché sous l’apparence comique","La recette d’un plat","La morale finale du livre","Le résumé du prologue"]'::jsonb, 0, 'Le prologue invite à briser l’os — en se moquant de ceux qui cherchent trop loin.', 2),
    ('2ae54fa9-6f9f-5c1c-84be-a5395b99f9cb'::uuid, '8f0387f2-f980-5d29-86c2-2a5c926f1c8c'::uuid, 'Quel précepteur réforme l’éducation de Gargantua ?', 'mcq', '["Ponocrates","Thubal Holoferne","Janotus de Bragmardo","Jobelin Bridé"]'::jsonb, 0, 'Journée réglée, corps entretenu, lectures commentées.', 3),
    ('e44a1cdc-475e-52a8-87a5-4241ecb19049'::uuid, '8f0387f2-f980-5d29-86c2-2a5c926f1c8c'::uuid, 'Quelle est l’origine de la guerre picrocholine ?', 'mcq', '["Une querelle de marchands de fouaces","Un vol de terres","Une insulte au roi","Un mariage rompu"]'::jsonb, 0, 'L’absurdité de la cause dénonce l’absurdité de la guerre.', 4),
    ('29fe7195-4f6b-53ae-9c16-ce927fd4ecaf'::uuid, '8f0387f2-f980-5d29-86c2-2a5c926f1c8c'::uuid, 'Quelle est la règle de l’abbaye de Thélème ?', 'mcq', '["« Fais ce que voudras »","« Prie et travaille »","« Silence et jeûne »","« Obéis à ton abbé »"]'::jsonb, 0, 'Un anti-monastère mixte, sans horloge ni contrainte.', 5),
    ('b3e12125-1abf-506c-a9c5-df0e53bf3874'::uuid, '8f0387f2-f980-5d29-86c2-2a5c926f1c8c'::uuid, 'Le rire est chez Rabelais un simple divertissement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une méthode critique : on ne discute pas une autorité dont on rit.', 6),
    ('e583e759-57bd-5c56-8225-90be1f6003c6'::uuid, '31e3dfcc-c695-5f01-a007-7650d519b3e3'::uuid, 'Où se déroule le roman ?', 'mcq', '["Dans une mine du nord de la France, le Voreux","Dans une usine parisienne","Dans un port normand","Dans une ferme du Beauce"]'::jsonb, 0, 'Zola s’était documenté sur place, à Anzin.', 1),
    ('40d0448a-d560-53c7-b5db-e9c89e38200c'::uuid, '31e3dfcc-c695-5f01-a007-7650d519b3e3'::uuid, 'Qui est Étienne Lantier ?', 'mcq', '["Un machineur au chômage devenu mineur puis meneur de la grève","Le directeur de la mine","Un journaliste parisien","Le fils Maheu"]'::jsonb, 0, 'Il s’instruit par la lecture et gagne en influence.', 2),
    ('c64a531f-3fef-50a5-b1ef-3e076789ac88'::uuid, '31e3dfcc-c695-5f01-a007-7650d519b3e3'::uuid, 'Que provoque le sabotage de Souvarine ?', 'mcq', '["L’inondation de la mine","Un incendie","L’arrêt de la grève","L’arrestation d’Étienne"]'::jsonb, 0, 'L’anarchiste russe agit seul, contre tous.', 3),
    ('725427dc-4601-5c18-8c9b-ee5092365335'::uuid, '31e3dfcc-c695-5f01-a007-7650d519b3e3'::uuid, 'Que devient Catherine ?', 'mcq', '["Elle meurt au fond, dans les bras d’Étienne","Elle épouse Chaval","Elle quitte la mine","Elle survit et part avec Étienne"]'::jsonb, 0, 'Chaval, lui, est tué au fond.', 4),
    ('391446f1-4e1e-53c6-9aec-211068dec5dc'::uuid, '31e3dfcc-c695-5f01-a007-7650d519b3e3'::uuid, 'Que signifie le titre du roman ?', 'mcq', '["Un mois du calendrier révolutionnaire, qui annonce une germination","Le nom de la fosse","Le nom du village","Un terme de géologie"]'::jsonb, 0, 'La révolte à venir germe sous les champs.', 5),
    ('a640e76b-d1d1-58d3-a772-45461f745011'::uuid, '31e3dfcc-c695-5f01-a007-7650d519b3e3'::uuid, 'La foule est traitée comme un simple décor.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est un personnage à part entière : c’est l’une des grandes réussites du roman.', 6),
    ('55656d7b-3a3f-5916-a4dc-68c9199c46b0'::uuid, '4d9eeaa1-111e-5ae7-988c-1a3c548ee30a'::uuid, 'Qui est Germinie Lacerteux ?', 'mcq', '["Une servante dont la maîtresse ignore la double vie","Une ouvrière d’usine","Une bourgeoise déclassée","Une actrice"]'::jsonb, 0, 'Alcool, dettes et rencontres nocturnes, derrière un dévouement irréprochable.', 1),
    ('cdcbaf7a-38e5-535f-bcbb-c6a2eea0c733'::uuid, '4d9eeaa1-111e-5ae7-988c-1a3c548ee30a'::uuid, 'Sur quel fait le roman s’appuie-t-il ?', 'mcq', '["La double vie de leur propre bonne, découverte à sa mort","Un fait divers judiciaire","Un rapport de police","Une légende populaire"]'::jsonb, 0, 'Le « document humain » est la méthode revendiquée.', 2),
    ('1e15db36-25a5-50d4-8f59-73e5849172ed'::uuid, '4d9eeaa1-111e-5ae7-988c-1a3c548ee30a'::uuid, 'Que revendique la préface du roman ?', 'mcq', '["Le droit du roman à décrire les basses classes","Le retour au roman historique","La primauté du style sur le sujet","La fin du roman"]'::jsonb, 0, 'Elle qualifie le livre de « clinique de l’Amour ».', 3),
    ('81e4ac6a-8d6c-5cdd-bc6a-3c33baadc14b'::uuid, '4d9eeaa1-111e-5ae7-988c-1a3c548ee30a'::uuid, 'Quel mouvement le roman annonce-t-il ?', 'mcq', '["Le naturalisme","Le romantisme","Le symbolisme","Le surréalisme"]'::jsonb, 0, 'Zola s’en réclamera explicitement.', 4),
    ('9b3f3627-8ef1-5cfe-aad3-d74e4a75f1ea'::uuid, '4d9eeaa1-111e-5ae7-988c-1a3c548ee30a'::uuid, 'Comment Germinie meurt-elle ?', 'mcq', '["À l’hôpital, épuisée et ruinée","Assassinée","De vieillesse chez sa maîtresse","Noyée"]'::jsonb, 0, 'Sa maîtresse découvre la vérité seulement après sa mort.', 5),
    ('424e0cbb-c94b-599a-841b-077f5ea3e6e9'::uuid, '4d9eeaa1-111e-5ae7-988c-1a3c548ee30a'::uuid, 'Le style des Goncourt est neutre et dépouillé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Leur « écriture artiste » est nerveuse et très sensorielle.', 6),
    ('b2057584-7b8c-573a-a4a7-d5896eda7c27'::uuid, '0efa604c-c956-5188-aba2-fcbff02a77ea'::uuid, 'À quel genre romanesque Gil Blas appartient-il ?', 'mcq', '["Le roman picaresque","Le roman épistolaire","Le roman historique","Le roman d’analyse"]'::jsonb, 0, 'Héros de basse condition, récit à la première personne, épisodes successifs.', 1),
    ('5995bdc9-734a-51b3-a0c2-de0262c113b0'::uuid, '0efa604c-c956-5188-aba2-fcbff02a77ea'::uuid, 'Quelle est la fonction principale de Gil Blas dans le roman ?', 'mcq', '["Valet successif d’une vingtaine de maîtres","Officier de marine","Marchand ambulant","Prêtre"]'::jsonb, 0, 'Chaque maître permet la satire d’une profession.', 2),
    ('a387a711-2710-5b1b-a0f6-a74c89b95a05'::uuid, '0efa604c-c956-5188-aba2-fcbff02a77ea'::uuid, 'Qui est le docteur Sangrado ?', 'mcq', '["Un médecin ignorant qui saigne tous ses patients","Un maître d’armes","Un juge corrompu","Un banquier"]'::jsonb, 0, 'La satire de la médecine est un morceau célèbre.', 3),
    ('b28370c0-4016-5831-8731-4a72343fd16c'::uuid, '0efa604c-c956-5188-aba2-fcbff02a77ea'::uuid, 'Quel pays sert de décor au roman ?', 'mcq', '["L’Espagne, décor transparent pour peindre la France","L’Italie","Le Portugal","La France directement"]'::jsonb, 0, 'C’est la France de la Régence qui est visée.', 4),
    ('ea6f63d8-aaf8-559d-8a8d-b4be3948e3c0'::uuid, '0efa604c-c956-5188-aba2-fcbff02a77ea'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Gil Blas se retire avec une fortune honnêtement acquise","Il meurt en prison","Il devient premier ministre","Il repart sur les routes"]'::jsonb, 0, 'Après la faveur, la prison et la disgrâce.', 5),
    ('a38eea9f-a7ed-5b4f-bf0e-8ef8bb4bfbce'::uuid, '0efa604c-c956-5188-aba2-fcbff02a77ea'::uuid, 'Gil Blas est un héros vertueux et constant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’adapte, ce qui fait de lui un observateur idéal des mœurs.', 6),
    ('2f8380f3-77ed-55c0-9ba9-1f37267d8a88'::uuid, '68f73dd3-6d51-5fa8-b737-f98da5857692'::uuid, 'Qui est Sirius Black ?', 'mcq', '["Le parrain de Harry, injustement accusé","Le meurtrier des parents de Harry","Un professeur de Poudlard","Un Détraqueur"]'::jsonb, 0, 'Le vrai traître est Peter Pettigrow.', 1),
    ('dcda9310-e4d2-5833-8624-3f88acadc63f'::uuid, '68f73dd3-6d51-5fa8-b737-f98da5857692'::uuid, 'Que sont les Détraqueurs ?', 'mcq', '["Des créatures qui aspirent les souvenirs heureux","Des gardiens fantômes du château","Des créatures de Voldemort ressuscitées","Des professeurs déguisés"]'::jsonb, 0, 'Rowling a confirmé qu’ils figurent la dépression.', 2),
    ('c1e333a9-acb0-57a2-a28c-c4da2b7c7784'::uuid, '68f73dd3-6d51-5fa8-b737-f98da5857692'::uuid, 'Quel sortilège Lupin enseigne-t-il à Harry ?', 'mcq', '["Le Patronus","L’Expelliarmus","Le Lumos","L’Impero"]'::jsonb, 0, 'Celui de Harry prend la forme d’un cerf, comme son père.', 3),
    ('73258839-edea-5a54-8eb2-c728b38425c2'::uuid, '68f73dd3-6d51-5fa8-b737-f98da5857692'::uuid, 'Sous quelle forme Peter Pettigrow se cachait-il ?', 'mcq', '["Le rat Croûtard","Un chien noir","Un hibou","Un chat"]'::jsonb, 0, 'Depuis douze ans, dans la famille Weasley.', 4),
    ('91546067-269d-53db-9fcf-a746e23e4385'::uuid, '68f73dd3-6d51-5fa8-b737-f98da5857692'::uuid, 'Quel objet permet de sauver Sirius et Buck ?', 'mcq', '["Le Retourneur de Temps","La cape d’invisibilité","La carte du Maraudeur","Le Choixpeau"]'::jsonb, 0, 'Premier usage du voyage dans le temps dans la série.', 5),
    ('32ed6b9c-cb64-562e-9126-70f3cd7b9ee9'::uuid, '68f73dd3-6d51-5fa8-b737-f98da5857692'::uuid, 'Ce tome conserve un partage simple entre bons et méchants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Innocent condamné, adulte lâche, justice défaillante : la série change de nature.', 6),
    ('3867ff8e-c99e-5fdd-bf5a-07ef1f7aad77'::uuid, '90debadd-19d4-523d-b4b7-bbb5c46795d7'::uuid, 'Que s’est-il passé à la création de la pièce, en 1830 ?', 'mcq', '["La « bataille d’Hernani » entre classiques et romantiques","Un triomphe unanime","Une interdiction royale","Un incendie du théâtre"]'::jsonb, 0, 'Sifflets, cris et bagarres — Gautier y portait un gilet rouge.', 1),
    ('9412d32a-76dc-5ea8-85e6-1d918877a30e'::uuid, '90debadd-19d4-523d-b4b7-bbb5c46795d7'::uuid, 'Qui aime Doña Sol ?', 'mcq', '["Hernani, don Carlos et don Ruy Gomez","Hernani seulement","Le roi seulement","Personne"]'::jsonb, 0, 'Trois rivaux : un proscrit, un roi, un vieillard.', 2),
    ('84094afa-0698-5fcf-83ad-f7a3acc40cf6'::uuid, '90debadd-19d4-523d-b4b7-bbb5c46795d7'::uuid, 'Quel serment lie Hernani à don Ruy Gomez ?', 'mcq', '["Mourir quand celui-ci sonnera du cor","Lui céder Doña Sol","Le servir dix ans","Quitter l’Espagne"]'::jsonb, 0, 'Le cor retentit le soir des noces.', 3),
    ('57e47863-8f3e-50eb-bbf8-d81e335a16f9'::uuid, '90debadd-19d4-523d-b4b7-bbb5c46795d7'::uuid, 'Quelle règle classique la pièce rejette-t-elle ?', 'mcq', '["Les unités de temps et de lieu","L’usage du vers","La division en actes","La présence d’un dénouement"]'::jsonb, 0, 'Elle applique la préface de Cromwell.', 4),
    ('665ab200-f2f9-50f7-90df-ddd48a0445cc'::uuid, '90debadd-19d4-523d-b4b7-bbb5c46795d7'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Par la mort des trois personnages principaux","Par le mariage heureux","Par le pardon du roi","Par la fuite d’Hernani"]'::jsonb, 0, 'Le serment l’emporte sur le pardon impérial.', 5),
    ('526f06c9-a53b-579c-8549-c400287f0e53'::uuid, '90debadd-19d4-523d-b4b7-bbb5c46795d7'::uuid, 'L’alexandrin y est respecté de façon classique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est disloqué dès les premiers vers par les enjambements : c’est une provocation.', 6),
    ('5ac2c847-ee5f-5ce1-83e6-4e22bd33d494'::uuid, '961db90a-5023-5e0b-bde8-6730bfd13049'::uuid, 'Quelle déesse déclenche l’action ?', 'mcq', '["Aphrodite, qui se venge du mépris d’Hippolyte","Artémis","Héra","Athéna"]'::jsonb, 0, 'Elle inspire à Phèdre une passion qu’elle n’a pas choisie.', 1),
    ('26f00f00-b00e-5721-b730-ddc2e1672f2d'::uuid, '961db90a-5023-5e0b-bde8-6730bfd13049'::uuid, 'Qui révèle le secret de Phèdre à Hippolyte ?', 'mcq', '["Sa nourrice","Thésée","Le chœur","Artémis"]'::jsonb, 0, 'Phèdre voulait mourir sans que rien ne se sache.', 2),
    ('5e305ffd-4372-5aac-bafc-fff42e42d5e9'::uuid, '961db90a-5023-5e0b-bde8-6730bfd13049'::uuid, 'Comment Phèdre accuse-t-elle Hippolyte ?', 'mcq', '["Par une tablette laissée avant son suicide","En parlant à Thésée","Par un témoin","Elle ne l’accuse pas"]'::jsonb, 0, 'Chez Euripide, elle est morte quand l’accusation éclate.', 3),
    ('0fda4e67-e296-597c-87d8-c01d471bc1ae'::uuid, '961db90a-5023-5e0b-bde8-6730bfd13049'::uuid, 'Comment Hippolyte meurt-il ?', 'mcq', '["Traîné par ses chevaux épouvantés par un taureau marin","Poignardé par Thésée","Empoisonné","Noyé"]'::jsonb, 0, 'Poséidon exauce la malédiction de Thésée.', 4),
    ('5e928ea8-60ed-549f-a37f-7f19bd4166e1'::uuid, '961db90a-5023-5e0b-bde8-6730bfd13049'::uuid, 'Quelle différence majeure avec la Phèdre de Racine ?', 'mcq', '["Chez Racine, Phèdre est vivante et avoue elle-même la vérité","Chez Racine, Hippolyte survit","Chez Racine, il n’y a pas de dieux mentionnés","Chez Racine, Thésée est mort"]'::jsonb, 0, 'L’accent se déplace de la vengeance divine vers la conscience coupable.', 5),
    ('4777a52b-73ae-5200-a747-38e662624cb5'::uuid, '961db90a-5023-5e0b-bde8-6730bfd13049'::uuid, 'La pièce d’Euripide est encadrée par des apparitions divines.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Aphrodite l’ouvre, Artémis la ferme : les dieux tiennent l’action.', 6),
    ('504fdd05-63b0-5d26-9e10-a025aa5b1366'::uuid, 'dc7c5bda-d9af-564d-b3c7-270f7bb3232d'::uuid, 'Qui est Tom Jones ?', 'mcq', '["Un enfant trouvé recueilli par le squire Allworthy","Un jeune noble de Londres","Un marin","Un pasteur de campagne"]'::jsonb, 0, 'Sa naissance inconnue est le ressort de tout le roman.', 1),
    ('f63d7b3a-ee37-5840-b384-a4b9cd6f6370'::uuid, 'dc7c5bda-d9af-564d-b3c7-270f7bb3232d'::uuid, 'Qui calomnie Tom ?', 'mcq', '["Blifil, le neveu hypocrite d’Allworthy","Sophia","Le squire Western","Partridge"]'::jsonb, 0, 'Il veut épouser Sophia et écarter son rival.', 2),
    ('5bc9ce65-570a-5f2a-9f21-4d4b13842845'::uuid, 'dc7c5bda-d9af-564d-b3c7-270f7bb3232d'::uuid, 'Comment le dénouement s’opère-t-il ?', 'mcq', '["Par la révélation de la naissance de Tom","Par un héritage inattendu","Par la mort de Blifil","Par un duel"]'::jsonb, 0, 'Il est le fils de la sœur d’Allworthy.', 3),
    ('9431a8e9-161a-528b-be7f-668fbfca2cae'::uuid, 'dc7c5bda-d9af-564d-b3c7-270f7bb3232d'::uuid, 'Quelle particularité présente la structure du roman ?', 'mcq', '["Chaque livre s’ouvre par un chapitre où l’auteur discute de l’art du roman","Il n’a pas de chapitres","Il est écrit en lettres","Il alterne prose et vers"]'::jsonb, 0, 'Fielding y théorise le « poème épique comique en prose ».', 4),
    ('05dee08a-7a42-5466-8ac6-41fad85210d9'::uuid, 'dc7c5bda-d9af-564d-b3c7-270f7bb3232d'::uuid, 'Quelle morale le roman défend-il ?', 'mcq', '["La vertu est la bonté du cœur, non la pureté sans faute","La vertu exige la chasteté absolue","Seule la naissance fait l’homme","La réussite justifie tout"]'::jsonb, 0, 'Tom fait des fautes et reste bon : c’est la thèse du livre.', 5),
    ('e2992c71-4e2c-5977-ab58-4009d8128e7a'::uuid, 'dc7c5bda-d9af-564d-b3c7-270f7bb3232d'::uuid, 'Le narrateur de Tom Jones s’efface derrière son récit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est omniprésent, ironique, et s’adresse constamment au lecteur.', 6),
    ('eeb04331-1e69-51c9-8f93-12f3dcac6741'::uuid, '1cfb3ddb-814b-5f3d-ba9f-b063e609f1d4'::uuid, 'Quel épisode fameux Gautier raconte-t-il de l’intérieur ?', 'mcq', '["La bataille d’Hernani, où il portait un gilet rouge","La Révolution de 1848","Le procès de Baudelaire","La Commune de Paris"]'::jsonb, 0, 'Il en fut l’un des acteurs les plus visibles.', 1),
    ('2b50eb70-74d3-5303-aea4-f4419a51f02e'::uuid, '1cfb3ddb-814b-5f3d-ba9f-b063e609f1d4'::uuid, 'Quelle est la nature de cet ouvrage ?', 'mcq', '["Un témoignage de participant, écrit quarante ans après","Une histoire littéraire savante","Un manifeste théorique","Un roman autobiographique"]'::jsonb, 0, 'Il paraît après la mort de Gautier, en 1874.', 2),
    ('deef3f50-5219-542a-b00a-e056405a515c'::uuid, '1cfb3ddb-814b-5f3d-ba9f-b063e609f1d4'::uuid, 'Comment Gautier présente-t-il le romantisme ?', 'mcq', '["Comme un mouvement de jeunesse autant qu’une révolution littéraire","Comme une école académique","Comme un mouvement religieux","Comme une mode passagère sans importance"]'::jsonb, 0, 'Vêtements, cheveux longs, provocations en font partie.', 3),
    ('7471f3b4-3dea-5d46-9c07-f2c9265bbcab'::uuid, '1cfb3ddb-814b-5f3d-ba9f-b063e609f1d4'::uuid, 'Quelle doctrine Gautier défend-il plus tard ?', 'mcq', '["L’art pour l’art","Le naturalisme","Le réalisme social","Le symbolisme"]'::jsonb, 0, 'Elle annonce le Parnasse ; voir la préface de Mademoiselle de Maupin.', 4),
    ('8b0da26e-b4df-5ce8-bb65-11be8ad10f57'::uuid, '1cfb3ddb-814b-5f3d-ba9f-b063e609f1d4'::uuid, 'Quels écrivains Gautier portraiture-t-il ?', 'mcq', '["Hugo, Nerval, Balzac, Pétrus Borel","Zola, Maupassant, Daudet","Racine et Corneille","Sartre et Camus"]'::jsonb, 0, 'Ce sont ses compagnons du « petit cénacle ».', 5),
    ('6a1c2b95-9a4b-5ab3-9210-4f089f1b7a51'::uuid, '1cfb3ddb-814b-5f3d-ba9f-b063e609f1d4'::uuid, 'L’ouvrage a été publié du vivant de Gautier.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il paraît deux ans après sa mort.', 6),
    ('75deb1fb-3cb8-5181-93d1-031772780401'::uuid, '96636925-d9ca-5a73-a2a8-c0df6a2bd6d7'::uuid, 'Pourquoi le combat est-il déchirant pour les deux familles ?', 'mcq', '["Elles sont unies par des mariages et des fiançailles","Elles se haïssent depuis des siècles","Elles se disputent un héritage","Elles servent le même roi"]'::jsonb, 0, 'Camille est fiancée à Curiace, Sabine est l’épouse d’Horace.', 1),
    ('5846650c-e3a0-5907-8f8d-a7307d187490'::uuid, '96636925-d9ca-5a73-a2a8-c0df6a2bd6d7'::uuid, 'Comment Horace vainc-t-il les trois Curiaces ?', 'mcq', '["Il feint de fuir pour les séparer, puis les tue l’un après l’autre","Il les affronte tous en même temps","Il gagne par ruse nocturne","Il ne les tue pas"]'::jsonb, 0, 'La ruse est racontée par un témoin, non montrée.', 2),
    ('763436b5-9f11-5e9d-9700-e28bbced7c4b'::uuid, '96636925-d9ca-5a73-a2a8-c0df6a2bd6d7'::uuid, 'Que fait Horace au retour ?', 'mcq', '["Il tue sa sœur Camille, qui maudit Rome","Il pardonne à sa sœur","Il refuse les honneurs","Il quitte Rome"]'::jsonb, 0, 'L’imprécation de Camille est l’un des morceaux les plus célèbres du théâtre.', 3),
    ('f3bdcf57-3d53-587b-b8c7-168c15bfec2f'::uuid, '96636925-d9ca-5a73-a2a8-c0df6a2bd6d7'::uuid, 'Quelle réplique célèbre le vieil Horace prononce-t-il ?', 'mcq', '["« Qu’il mourût ! »","« Je suis maître de moi »","« Ô rage, ô désespoir »","« Rome n’est plus dans Rome »"]'::jsonb, 0, 'Il aurait préféré la mort de son fils au déshonneur d’une fuite.', 4),
    ('873ac099-6a1b-53f3-810e-f5ec09b35a63'::uuid, '96636925-d9ca-5a73-a2a8-c0df6a2bd6d7'::uuid, 'Comment se termine le procès d’Horace ?', 'mcq', '["Le roi Tulle le sauve au nom du service rendu à l’État","Il est exécuté","Il est exilé","Il est acquitté par le peuple"]'::jsonb, 0, 'La raison d’État l’emporte sur la justice ordinaire.', 5),
    ('401dfc7f-a0d6-5d0c-8db2-98cb383d481c'::uuid, '96636925-d9ca-5a73-a2a8-c0df6a2bd6d7'::uuid, 'Curiace refuse de combattre pour Albe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il accepte, mais en souffrant : il incarne l’humanité déchirée face à Horace.', 6),
    ('06804728-faac-5817-aeb9-cf32c2d84393'::uuid, 'f64efef0-fc34-5342-aaca-9b80024aaa67'::uuid, 'Où se déroule la pièce ?', 'mcq', '["Dans un salon Second Empire sans fenêtre ni miroir","Dans une prison","Dans une chambre d’hôtel","Sur une plage"]'::jsonb, 0, 'Ni sommeil, ni bourreau, ni sortie : le décor est l’enfer même.', 1),
    ('4a22f8f5-325f-5f72-84c5-75f0571859d3'::uuid, 'f64efef0-fc34-5342-aaca-9b80024aaa67'::uuid, 'Qui sont les trois personnages ?', 'mcq', '["Garcin, Inès et Estelle","Garcin, Inès et le garçon d’étage","Trois soldats","Un couple et son enfant"]'::jsonb, 0, 'Un déserteur, une employée des postes, une mondaine.', 2),
    ('9da40996-0e34-5c01-892a-6f115233a98b'::uuid, 'f64efef0-fc34-5342-aaca-9b80024aaa67'::uuid, 'Pourquoi n’y a-t-il pas besoin de bourreau ?', 'mcq', '["Chacun est le bourreau des deux autres","Le bourreau viendra plus tard","Ils sont innocents","Ils dorment sans cesse"]'::jsonb, 0, 'Le triangle des désirs est sans issue.', 3),
    ('469d42e1-4646-5dec-8ea0-e6282518c6b2'::uuid, 'f64efef0-fc34-5342-aaca-9b80024aaa67'::uuid, 'Que se passe-t-il quand la porte s’ouvre ?', 'mcq', '["Personne ne sort","Ils sortent tous","Garcin seul s’échappe","Le garçon les emmène"]'::jsonb, 0, 'Ils sont liés par le besoin du regard des autres.', 4),
    ('cc01f8b0-f099-5089-bc08-793a727a3136'::uuid, 'f64efef0-fc34-5342-aaca-9b80024aaa67'::uuid, 'Que signifie « l’enfer, c’est les autres » ?', 'mcq', '["Le regard d’autrui me fige en objet et me juge","Les autres sont mauvais par nature","La solitude est préférable","L’enfer est une invention sociale"]'::jsonb, 0, 'C’est une thèse philosophique, pas une misanthropie.', 5),
    ('793cfe1f-ebe2-535e-877b-cccabc12f453'::uuid, 'f64efef0-fc34-5342-aaca-9b80024aaa67'::uuid, 'La pièce illustre la philosophie existentialiste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’homme est ce qu’il fait de ce qu’on a fait de lui : il n’y a pas d’essence, seulement des actes.', 6),
    ('79523fe7-18f7-502d-8e93-108e2794fb83'::uuid, '4cb51dd0-a53f-5a95-92e5-352d11444452'::uuid, 'Quel est le sujet annoncé du poème ?', 'mcq', '["La colère d’Achille","La chute de Troie","Le retour d’Ulysse","La fondation de Rome"]'::jsonb, 0, 'Le poème couvre cinquante et un jours de la dixième année de guerre.', 1),
    ('9521b197-0164-57be-80c1-e14017a885c6'::uuid, '4cb51dd0-a53f-5a95-92e5-352d11444452'::uuid, 'Pourquoi Achille se retire-t-il du combat ?', 'mcq', '["Agamemnon lui a pris sa captive Briséis","Il est blessé","Les dieux le lui ordonnent","Il veut rentrer chez lui"]'::jsonb, 0, 'L’affront à son honneur déclenche toute l’intrigue.', 2),
    ('606f0b77-fa48-5aaf-a336-e310b19c0b48'::uuid, '4cb51dd0-a53f-5a95-92e5-352d11444452'::uuid, 'Qu’est-ce qui fait revenir Achille au combat ?', 'mcq', '["La mort de Patrocle, tué par Hector","Les excuses d’Agamemnon","Un oracle","La menace des dieux"]'::jsonb, 0, 'La colère change d’objet : elle vise désormais Hector.', 3),
    ('365fb343-7b86-57ce-9013-3e3487ae676e'::uuid, '4cb51dd0-a53f-5a95-92e5-352d11444452'::uuid, 'Sur quelle scène le poème se termine-t-il ?', 'mcq', '["Priam suppliant Achille de lui rendre le corps d’Hector","La prise de Troie","La mort d’Achille","Le départ des Grecs"]'::jsonb, 0, 'Les deux ennemis y pleurent ensemble.', 4),
    ('d95b807c-b84f-5edc-a6ab-7bfdd864ff86'::uuid, '4cb51dd0-a53f-5a95-92e5-352d11444452'::uuid, 'Qu’est-ce qu’une épithète de nature ?', 'mcq', '["Une formule fixe accolée à un nom, comme Achille « aux pieds légers »","Une comparaison développée","Une invocation aux dieux","Un catalogue de guerriers"]'::jsonb, 0, 'Ces formules facilitaient la récitation orale.', 5),
    ('8c7dfa05-b6da-5ea7-945e-312327d5a2ef'::uuid, '4cb51dd0-a53f-5a95-92e5-352d11444452'::uuid, 'Le poème glorifie la guerre sans en montrer le coût.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La compassion y est égale pour les deux camps : le coût humain est constamment montré.', 6),
    ('1b2643cd-7672-54b5-b174-2c8a31d73e3d'::uuid, '16976775-317a-56f0-86a9-3de54f816122'::uuid, 'De quel type de textes le recueil est-il composé ?', 'mcq', '["De poèmes en prose et de quelques vers libres","De sonnets","De lettres","De récits de voyage"]'::jsonb, 0, 'Le vers libre y apparaît quinze ans avant sa généralisation.', 1),
    ('64f0cf5c-b648-53cf-ae5d-97c53a8d4bde'::uuid, '16976775-317a-56f0-86a9-3de54f816122'::uuid, 'Qui a fait publier le recueil ?', 'mcq', '["Verlaine, en 1886","Rimbaud lui-même","Mallarmé","La famille de Rimbaud"]'::jsonb, 0, 'Rimbaud était alors en Afrique et ne s’en est pas occupé.', 2),
    ('690f4602-b8fd-597a-9141-3d061d35fc30'::uuid, '16976775-317a-56f0-86a9-3de54f816122'::uuid, 'Quel programme les Illuminations réalisent-elles ?', 'mcq', '["Celui des lettres du voyant : se faire voyant par le dérèglement des sens","Le programme parnassien","La doctrine de l’art pour l’art","Le naturalisme en poésie"]'::jsonb, 0, 'Le poème ne décrit plus : il produit une réalité.', 3),
    ('edc1848b-4a09-581f-b2f4-60bc90977d91'::uuid, '16976775-317a-56f0-86a9-3de54f816122'::uuid, 'Que peut-on dire de l’ordre des textes ?', 'mcq', '["Il n’est pas sûrement celui voulu par Rimbaud","Il est chronologique","Il suit un plan strict en quatre parties","Il a été fixé par l’auteur avant son départ"]'::jsonb, 0, 'Le manuscrit a circulé sans instructions claires.', 4),
    ('fa9e8caa-6911-51cc-8950-42f77dc07c12'::uuid, '16976775-317a-56f0-86a9-3de54f816122'::uuid, 'Que fait Rimbaud après ces textes ?', 'mcq', '["Il cesse d’écrire, à vingt ans","Il publie encore dix recueils","Il devient critique littéraire","Il retourne à la poésie régulière"]'::jsonb, 0, 'Le silence fait partie de la légende — et de l’œuvre.', 5),
    ('a05e908b-7a3a-545c-9752-a71b01c41726'::uuid, '16976775-317a-56f0-86a9-3de54f816122'::uuid, 'Les Illuminations racontent une histoire suivie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des visions juxtaposées, sans récit ni sujet lyrique stable.', 6),
    ('19e888e7-d91e-592f-aa93-9054f2e94656'::uuid, '0371484b-4d8a-5f4e-b73e-91a741aa23fe'::uuid, 'Pourquoi la flotte grecque est-elle immobilisée ?', 'mcq', '["Les dieux exigent le sacrifice d’Iphigénie pour rendre les vents","Une épidémie frappe l’armée","Une tempête a brisé les navires","Achille refuse de combattre"]'::jsonb, 0, 'Le chantage religieux met en marche toute la pièce.', 1),
    ('4bb09acc-b2ea-5c58-9d35-b520aa025237'::uuid, '0371484b-4d8a-5f4e-b73e-91a741aa23fe'::uuid, 'Sous quel prétexte Iphigénie est-elle appelée à Aulis ?', 'mcq', '["Un mariage avec Achille","Une cérémonie religieuse","La maladie de son père","Un conseil de guerre"]'::jsonb, 0, 'Agamemnon tente ensuite de la renvoyer, en vain.', 2),
    ('1cc58ff8-8a83-5782-b685-e3eb76aac12f'::uuid, '0371484b-4d8a-5f4e-b73e-91a741aa23fe'::uuid, 'Qui est Ériphile ?', 'mcq', '["Une captive amoureuse d’Achille, qui dénonce la fuite","La sœur d’Iphigénie","Une prêtresse d’Artémis","La confidente de Clytemnestre"]'::jsonb, 0, 'Racine l’invente pour éviter le miracle final d’Euripide.', 3),
    ('7a50a5a1-2cd5-568b-b818-27ec82b64cfa'::uuid, '0371484b-4d8a-5f4e-b73e-91a741aa23fe'::uuid, 'Comment la pièce se dénoue-t-elle ?', 'mcq', '["Ériphile se tue sur l’autel : c’est elle que les dieux voulaient","Iphigénie est sacrifiée","Achille enlève Iphigénie","Une biche est substituée par Artémis"]'::jsonb, 0, 'La vraisemblance est sauve, et la victime devient coupable.', 4),
    ('44880d33-9838-5652-9095-c769fb4a01f7'::uuid, '0371484b-4d8a-5f4e-b73e-91a741aa23fe'::uuid, 'Quelle attitude adopte Iphigénie face au sacrifice ?', 'mcq', '["Elle accepte de mourir par obéissance","Elle s’enfuit","Elle maudit son père","Elle demande à Achille de tuer Agamemnon"]'::jsonb, 0, 'Son obéissance rend la cruauté paternelle plus visible encore.', 5),
    ('47636d7b-4b59-577f-8a1c-48d861dc3b51'::uuid, '0371484b-4d8a-5f4e-b73e-91a741aa23fe'::uuid, 'Racine reprend le dénouement d’Euripide à l’identique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il remplace la substitution divine par le personnage inventé d’Ériphile.', 6),
    ('ef89d521-bc54-58e2-b8a1-8f88b9a8e7db'::uuid, '79db633d-b125-525e-af38-3f4181b88230'::uuid, 'Pourquoi Gérard vient-il à La Quartfourche ?', 'mcq', '["Pour étudier un manuscrit","Pour y passer des vacances","Pour y enseigner","Pour acheter le domaine"]'::jsonb, 0, 'Il y découvre une maisonnée étrange et une lettre cachée.', 1),
    ('01910274-3d7d-559a-b6bd-042b9d3519f8'::uuid, '79db633d-b125-525e-af38-3f4181b88230'::uuid, 'Qu’est-ce qui fait naître le rêve de Gérard ?', 'mcq', '["Une ancienne lettre d’amour trouvée par hasard","Un portrait dans le salon","Le récit de l’abbé","Une rencontre au village"]'::jsonb, 0, 'Il aime une femme qu’il n’a jamais vue.', 2),
    ('04b1d39f-8569-5899-aa61-198fca53824f'::uuid, '79db633d-b125-525e-af38-3f4181b88230'::uuid, 'Que se passe-t-il quand Isabelle paraît ?', 'mcq', '["La réalité détruit l’image rêvée","Elle épouse Gérard","Elle s’enfuit à nouveau","Elle reprend son fils"]'::jsonb, 0, 'Elle est égoïste, calculatrice et indifférente à Casimir.', 3),
    ('1585aa4c-5abd-50ac-b91f-0be85eb033b7'::uuid, '79db633d-b125-525e-af38-3f4181b88230'::uuid, 'Comment Gide classe-t-il ce livre ?', 'mcq', '["Parmi ses « récits »","Parmi ses « soties »","Parmi ses romans","Parmi ses essais"]'::jsonb, 0, 'Il ne reconnaissait qu’un seul « roman » : Les Faux-Monnayeurs.', 4),
    ('7f7020df-e4a3-5fb3-bbc9-3ce21dde2fd9'::uuid, '79db633d-b125-525e-af38-3f4181b88230'::uuid, 'Quel est le sujet profond du livre ?', 'mcq', '["Le décalage entre l’image rêvée et la personne réelle","La ruine de l’aristocratie","L’éducation d’un enfant infirme","La vie de province"]'::jsonb, 0, 'La littérature y est accusée de fabriquer des attentes.', 5),
    ('06dd1188-3a20-5671-85b3-a100a9044fa3'::uuid, '79db633d-b125-525e-af38-3f4181b88230'::uuid, 'Le récit se termine sur la restauration du domaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le domaine est vendu et les arbres abattus : tout le décor du rêve disparaît.', 6),
    ('e460432f-4696-557b-91f3-26bc2a412ea1'::uuid, 'b09a8acd-8ad5-551b-8d6b-561c8916452e'::uuid, 'Quel conflit traverse le roman ?', 'mcq', '["L’opposition entre Saxons vaincus et Normands conquérants","La guerre de Cent Ans","La guerre des Deux-Roses","La conquête de l’Irlande"]'::jsonb, 0, 'Le prince Jean complote pendant l’absence de Richard.', 1),
    ('3e1bfaf1-bcf9-5e67-bc91-bee8ade65efb'::uuid, 'b09a8acd-8ad5-551b-8d6b-561c8916452e'::uuid, 'Quel personnage légendaire apparaît comme allié ?', 'mcq', '["Robin des Bois","Merlin","Le roi Arthur","Guillaume Tell"]'::jsonb, 0, 'Il aide lors du siège de Torquilstone.', 2),
    ('8230379b-6df1-59fe-8638-4c9a12578e04'::uuid, 'b09a8acd-8ad5-551b-8d6b-561c8916452e'::uuid, 'Qui est Rebecca ?', 'mcq', '["Une jeune juive accusée de sorcellerie","La sœur d’Ivanhoé","La fiancée du prince Jean","Une religieuse"]'::jsonb, 0, 'Elle est sauvée lors d’un duel judiciaire, mais écartée du dénouement.', 3),
    ('9c7b0aba-0efb-59fd-ba5b-543ab167bd36'::uuid, 'b09a8acd-8ad5-551b-8d6b-561c8916452e'::uuid, 'Quel genre ce roman fixe-t-il ?', 'mcq', '["Le roman historique","Le roman gothique","Le roman épistolaire","Le roman policier"]'::jsonb, 0, 'Intrigue fictive dans une époque documentée, avec personnages réels en arrière-plan.', 4),
    ('c3b06b0c-e672-54bc-8e4c-4c88288cdc7c'::uuid, 'b09a8acd-8ad5-551b-8d6b-561c8916452e'::uuid, 'Quels écrivains français ont suivi ce modèle ?', 'mcq', '["Hugo, Dumas et Balzac","Racine et Corneille","Zola et Maupassant","Sartre et Camus"]'::jsonb, 0, 'Notre-Dame de Paris en est l’héritier direct.', 5),
    ('0a952a6d-5cb2-5575-bfaa-dd60947722df'::uuid, 'b09a8acd-8ad5-551b-8d6b-561c8916452e'::uuid, 'Le roman se déroule au XVe siècle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se situe à la fin du XIIe siècle, au retour de la troisième croisade.', 6),
    ('1cec5f55-cd9e-501c-bdbc-c304b40ebe87'::uuid, '2cbe2e23-ca3e-5aed-b728-32897879e0e2'::uuid, 'Que tente de raconter Jacques tout au long du livre ?', 'mcq', '["L’histoire de ses amours","Sa carrière militaire","Le voyage de son maître","La vie de Madame de La Pommeraye"]'::jsonb, 0, 'Il n’y parvient jamais : les interruptions sont le principe du livre.', 1),
    ('3a0a665a-3588-5c42-9dc8-08edcfb69bab'::uuid, '2cbe2e23-ca3e-5aed-b728-32897879e0e2'::uuid, 'Qui interrompt le plus souvent le récit ?', 'mcq', '["Le narrateur lui-même, qui s’adresse au lecteur","Le maître","L’aubergiste","Un notaire"]'::jsonb, 0, 'Il se moque des attentes du lecteur et propose plusieurs suites.', 2),
    ('529562ff-9a18-59a2-82e6-9aacb5234d01'::uuid, '2cbe2e23-ca3e-5aed-b728-32897879e0e2'::uuid, 'Quelle formule résume le fatalisme de Jacques ?', 'mcq', '["« Tout est écrit là-haut, sur le grand rouleau »","« Il faut cultiver notre jardin »","« Tout est pour le mieux »","« Le hasard n’existe pas »"]'::jsonb, 0, 'Il agit pourtant comme s’il était libre.', 3),
    ('ab3864a4-9be9-5c24-8986-416290c422da'::uuid, '2cbe2e23-ca3e-5aed-b728-32897879e0e2'::uuid, 'Quel roman anglais a inspiré Diderot ?', 'mcq', '["Tristram Shandy, de Sterne","Robinson Crusoé","Pamela","Gulliver"]'::jsonb, 0, 'Même goût de la digression et de l’adresse au lecteur.', 4),
    ('0facfe0e-945a-57ff-9ebf-3090c4dee199'::uuid, '2cbe2e23-ca3e-5aed-b728-32897879e0e2'::uuid, 'Quand le livre a-t-il été publié ?', 'mcq', '["En 1796, après la mort de Diderot","En 1765","En 1749","En 1830"]'::jsonb, 0, 'Il avait circulé sous forme manuscrite auparavant.', 5),
    ('13133480-419e-5a5e-8632-b13f1046cc99'::uuid, '2cbe2e23-ca3e-5aed-b728-32897879e0e2'::uuid, 'Le livre respecte les conventions du roman de son temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un anti-roman : il démonte ses propres procédés et annonce le Nouveau Roman.', 6),
    ('15af098e-e728-5075-a4d1-ef0be96a9609'::uuid, 'fac4bffc-deb6-52d3-9438-2efe6fb51cca'::uuid, 'Que font le Papet et Ugolin pour s’emparer du domaine ?', 'mcq', '["Ils bouchent secrètement la source","Ils incendient la ferme","Ils falsifient un testament","Ils achètent les dettes"]'::jsonb, 0, 'Le crime est passif, ce qui le rend plus terrible.', 1),
    ('92f23123-bd04-55e1-8da3-6b54934927b7'::uuid, 'fac4bffc-deb6-52d3-9438-2efe6fb51cca'::uuid, 'Qui est Jean de Florette ?', 'mcq', '["Un bossu ancien percepteur, venu cultiver le domaine hérité","Un fermier du village","Un notaire marseillais","Le fils du Papet"]'::jsonb, 0, 'Il arrive avec sa femme Aimée et sa fille Manon.', 2),
    ('43d6e939-c792-5e08-a2c6-34f610b49a6b'::uuid, 'fac4bffc-deb6-52d3-9438-2efe6fb51cca'::uuid, 'Comment Jean meurt-il ?', 'mcq', '["Tué par une charge de mine en creusant pour trouver l’eau","De maladie","Assassiné par Ugolin","Noyé"]'::jsonb, 0, 'Il refusait d’abandonner malgré l’épuisement et les dettes.', 3),
    ('776955e5-62e6-55c7-9313-62650a0c7382'::uuid, 'fac4bffc-deb6-52d3-9438-2efe6fb51cca'::uuid, 'Qui voit les Soubeyran déboucher la source ?', 'mcq', '["Manon, cachée","Le curé","Aimée","Personne"]'::jsonb, 0, 'C’est le point de départ de la vengeance du second volume.', 4),
    ('baa15c2b-8971-5b9c-9844-84a76a6b9d78'::uuid, 'fac4bffc-deb6-52d3-9438-2efe6fb51cca'::uuid, 'Quel rôle joue le village dans le drame ?', 'mcq', '["Il sait et se tait : le silence est complice","Il aide Jean à trouver l’eau","Il dénonce les Soubeyran","Il ignore tout jusqu’à la fin"]'::jsonb, 0, 'La tragédie paysanne repose sur ce silence.', 5),
    ('f6597a69-1ec6-5f94-94c0-c90ab45a0555'::uuid, 'fac4bffc-deb6-52d3-9438-2efe6fb51cca'::uuid, 'Le roman a été écrit avant le film de Pagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pagnol l’écrit en 1963 d’après son film Manon des sources de 1952.', 6),
    ('2b4e5965-15e7-530d-9804-c03f907758fc'::uuid, '9584acba-ea0c-574b-ba60-5203f10bcbdc'::uuid, 'Que contient le Journal des faux-monnayeurs ?', 'mcq', '["Les notes prises pendant l’écriture du roman","La suite du roman","Une autobiographie de Gide","Des critiques du roman par ses lecteurs"]'::jsonb, 0, 'Hésitations, choix de construction, doutes.', 1),
    ('3b0922f8-70e7-59c3-808a-30825e9e24cd'::uuid, '9584acba-ea0c-574b-ba60-5203f10bcbdc'::uuid, 'Quel personnage du roman tient lui aussi un journal ?', 'mcq', '["Édouard, romancier qui prépare Les Faux-Monnayeurs","Bernard","Olivier","Le comte de Passavant"]'::jsonb, 0, 'C’est le cœur de la mise en abyme.', 2),
    ('ab517f3c-955b-53bf-87b6-4dbc21f371fd'::uuid, '9584acba-ea0c-574b-ba60-5203f10bcbdc'::uuid, 'Que veut « purger » Gide du roman ?', 'mcq', '["Tout ce qui n’appartient pas spécifiquement au roman","Les dialogues","La psychologie","Les personnages secondaires"]'::jsonb, 0, 'Ni description gratuite, ni événement raconté pour lui-même.', 3),
    ('b6fa7ab3-dac1-5144-a065-57e6cb0bbd4a'::uuid, '9584acba-ea0c-574b-ba60-5203f10bcbdc'::uuid, 'Quand ce journal a-t-il été publié ?', 'mcq', '["En 1926, un an après le roman","La même année que le roman","Après la mort de Gide","Avant le roman"]'::jsonb, 0, 'Il éclaire toutes les décisions techniques du livre.', 4),
    ('67a00889-81df-57ac-b377-cf3887b73760'::uuid, '9584acba-ea0c-574b-ba60-5203f10bcbdc'::uuid, 'Quel geste littéraire ce livre inaugure-t-il en France ?', 'mcq', '["Publier l’atelier d’un livre comme livre à part entière","La publication en feuilleton","L’écriture collective","Le roman épistolaire moderne"]'::jsonb, 0, 'De nombreux écrivains contemporains l’ont repris.', 5),
    ('abb533c9-ad8b-505a-a2af-a808e37004da'::uuid, '9584acba-ea0c-574b-ba60-5203f10bcbdc'::uuid, 'Le journal a été écrit après coup, une fois le roman terminé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est écrit pendant : c’est ce qui en fait un document sur le travail en cours.', 6),
    ('691ed17e-69c4-5231-b02e-a53acbd4b278'::uuid, '9ce9d3d2-c466-5c6a-87ba-16c7440aa1fb'::uuid, 'Sur combien de temps s’étend le Journal de Gide ?', 'mcq', '["Environ soixante ans","Dix ans","Vingt ans","Cinq ans"]'::jsonb, 0, 'De sa vingtaine jusqu’à sa mort en 1951.', 1),
    ('d73e4f90-64e2-572e-9144-1ef67f040928'::uuid, '9ce9d3d2-c466-5c6a-87ba-16c7440aa1fb'::uuid, 'Quel voyage a provoqué une enquête parlementaire ?', 'mcq', '["Le Voyage au Congo, en 1927","Le voyage en URSS","Le voyage en Algérie","Le voyage en Italie"]'::jsonb, 0, 'Gide y dénonçait les abus des compagnies concessionnaires.', 2),
    ('8f5b7335-7605-5f12-8e09-7b5e03a24cfe'::uuid, '9ce9d3d2-c466-5c6a-87ba-16c7440aa1fb'::uuid, 'Quelle rupture politique le Journal documente-t-il ?', 'mcq', '["Sa rupture avec le communisme après le Retour de l’URSS","Son ralliement à la monarchie","Sa rupture avec la NRF","Son engagement dans la Résistance armée"]'::jsonb, 0, 'Le Retour de l’URSS (1936) fit scandale à gauche.', 3),
    ('2152a0ce-4db3-52c4-bd53-51ba836faeca'::uuid, '9ce9d3d2-c466-5c6a-87ba-16c7440aa1fb'::uuid, 'Quel prix Gide a-t-il reçu en 1947 ?', 'mcq', '["Le prix Nobel de littérature","Le Goncourt","Le grand prix de l’Académie","Le prix Femina"]'::jsonb, 0, 'Quatre ans avant sa mort.', 4),
    ('317d3311-564a-50d6-9a79-14e7381058d4'::uuid, '9ce9d3d2-c466-5c6a-87ba-16c7440aa1fb'::uuid, 'Quel intérêt présente un journal d’écrivain ?', 'mcq', '["Il montre le travail, les hésitations et la vie d’où sort l’œuvre","Il remplace l’œuvre","Il donne les clés définitives des romans","Il n’a qu’un intérêt biographique"]'::jsonb, 0, 'C’est un genre littéraire à part entière.', 5),
    ('7e8df16b-0432-50fc-b3cc-efdad668d219'::uuid, '9ce9d3d2-c466-5c6a-87ba-16c7440aa1fb'::uuid, 'Le Journal de Gide ne parle que de littérature.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Voyages, santé, politique, religion et vie quotidienne y tiennent une place immense.', 6),
    ('8f766bf3-daac-59b5-968f-c673f05d37a5'::uuid, '314a2e7d-a2b8-5233-a59a-60ae8dc07219'::uuid, 'Quelle est la forme du roman ?', 'mcq', '["Un roman épistolaire en six parties","Un roman-mémoires","Un conte philosophique","Un dialogue"]'::jsonb, 0, 'Les lettres échangées portent toute la narration.', 1),
    ('fde00bac-91e3-5109-9433-cc0149bdc9fc'::uuid, '314a2e7d-a2b8-5233-a59a-60ae8dc07219'::uuid, 'Pourquoi Julie ne peut-elle épouser Saint-Preux ?', 'mcq', '["Il est roturier, son père refuse la mésalliance","Il est déjà marié","Il part à la guerre","Elle ne l’aime pas"]'::jsonb, 0, 'Elle épousera M. de Wolmar par obéissance.', 2),
    ('c0af3dba-5637-5c8a-ae45-8672144b818d'::uuid, '314a2e7d-a2b8-5233-a59a-60ae8dc07219'::uuid, 'Qu’est-ce que Clarens ?', 'mcq', '["Le domaine où Julie fonde une communauté rurale exemplaire","Le village natal de Saint-Preux","Un couvent suisse","Un port du Léman"]'::jsonb, 0, 'Travail partagé, vertu et transparence : c’est une utopie.', 3),
    ('c69ca1f3-db03-541c-bd90-dab6f8b9893d'::uuid, '314a2e7d-a2b8-5233-a59a-60ae8dc07219'::uuid, 'Comment Julie meurt-elle ?', 'mcq', '["Après avoir sauvé son fils de la noyade","De chagrin","En couches","Assassinée"]'::jsonb, 0, 'Sa dernière lettre avoue qu’elle n’a jamais cessé d’aimer Saint-Preux.', 4),
    ('9931f0f0-0862-5b37-97d7-8c3a1768750b'::uuid, '314a2e7d-a2b8-5233-a59a-60ae8dc07219'::uuid, 'Quel mouvement le roman annonce-t-il ?', 'mcq', '["Le romantisme, par la sensibilité et le rôle de la nature","Le naturalisme","Le classicisme","Le surréalisme"]'::jsonb, 0, 'Le paysage y accompagne et exprime les états d’âme.', 5),
    ('3dde309a-0011-51c4-b724-dc6f71a426f0'::uuid, '314a2e7d-a2b8-5233-a59a-60ae8dc07219'::uuid, 'Le roman fut un échec commercial.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Plus de soixante éditions en quarante ans : c’est le plus grand succès du siècle.', 6),
    ('0359234d-d949-511d-a8ea-f4b21670f62a'::uuid, '4278035d-5282-59e9-868f-e17dad0e1db8'::uuid, 'Pourquoi Louis revient-il ?', 'mcq', '["Pour annoncer sa mort prochaine","Pour un héritage","Pour un mariage","Pour se réconcilier avec Antoine"]'::jsonb, 0, 'Le prologue l’annonce au public dès le début.', 1),
    ('6caad22a-5632-5a32-8d1f-e2718bae6043'::uuid, '4278035d-5282-59e9-868f-e17dad0e1db8'::uuid, 'Que fait Louis à la fin ?', 'mcq', '["Il repart sans avoir rien dit","Il annonce la nouvelle","Il reste vivre au pays","Il emmène Suzanne"]'::jsonb, 0, 'L’épilogue évoque au conditionnel un cri jamais poussé.', 2),
    ('7317378f-ce71-5f79-9441-ea596912184f'::uuid, '4278035d-5282-59e9-868f-e17dad0e1db8'::uuid, 'Quelle est la particularité de la langue de Lagarce ?', 'mcq', '["Les phrases se reprennent et se corrigent en direct","Elle est en alexandrins","Elle est très argotique","Elle imite le style juridique"]'::jsonb, 0, 'La forme dit le sujet : on parle pour ne pas dire.', 3),
    ('47eae599-a4aa-58e2-a8ba-f3ea362397bb'::uuid, '4278035d-5282-59e9-868f-e17dad0e1db8'::uuid, 'Qui est Catherine ?', 'mcq', '["La belle-sœur, que Louis n’avait jamais rencontrée","La mère de Louis","Sa sœur","Son amie d’enfance"]'::jsonb, 0, 'Sa politesse gênée souligne l’étrangeté de la situation.', 4),
    ('ef1a19dc-6cf9-56fc-8ec9-fabbb678338b'::uuid, '4278035d-5282-59e9-868f-e17dad0e1db8'::uuid, 'Qui a adapté la pièce au cinéma en 2016 ?', 'mcq', '["Xavier Dolan","François Ozon","Arnaud Desplechin","Patrice Chéreau"]'::jsonb, 0, 'Le film a fait connaître la pièce à un très large public.', 5),
    ('8881fa9d-1d4b-5fa1-85d5-557ee95beaa2'::uuid, '4278035d-5282-59e9-868f-e17dad0e1db8'::uuid, 'La pièce comporte de nombreux rebondissements.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne s’y passe presque rien : l’aveu impossible tient lieu d’intrigue.', 6),
    ('494b1260-e6e7-5d1c-97c6-0395e80a37bf'::uuid, '56fc85ae-6658-5210-b98a-29ad5a14678d'::uuid, 'Que signifie le titre du recueil ?', 'mcq', '["Les poèmes de jeunesse de Clément — son « adolescence »","Un éloge de la clémence royale","Un hommage au pape Clément","Une allégorie du printemps"]'::jsonb, 0, 'Le jeu de mots sur son prénom est délibéré.', 1),
    ('72cd9170-5605-58e2-a53b-e88731a134fd'::uuid, '56fc85ae-6658-5210-b98a-29ad5a14678d'::uuid, 'Quelle est la nouveauté du recueil dans l’histoire du livre ?', 'mcq', '["Le poète compose lui-même son recueil et en surveille l’impression","Il est imprimé en couleurs","Il est publié anonymement","Il est écrit en latin"]'::jsonb, 0, 'Geste neuf à l’époque de l’imprimerie naissante.', 2),
    ('d44b63c2-b26a-52b6-99da-7d0fc9119605'::uuid, '56fc85ae-6658-5210-b98a-29ad5a14678d'::uuid, 'De quoi parle l’« Épître au roi pour avoir été dérobé » ?', 'mcq', '["Du vol commis par son valet, prétexte à demander de l’argent","D’une bataille","D’un exil","D’un procès en hérésie"]'::jsonb, 0, 'Marot y fait de l’humour une stratégie de requête.', 3),
    ('75f495ea-81b6-58f8-8585-f79b0910f228'::uuid, '56fc85ae-6658-5210-b98a-29ad5a14678d'::uuid, 'Quelles formes Marot pratique-t-il ?', 'mcq', '["Épîtres, ballades, rondeaux, épigrammes","Sonnets et odes uniquement","Tragédies","Romans en vers"]'::jsonb, 0, 'Ce sont les formes médiévales que la Pléiade rejettera bientôt.', 4),
    ('6c05a04e-a1cb-5169-acf4-2fee98f00996'::uuid, '56fc85ae-6658-5210-b98a-29ad5a14678d'::uuid, 'Qu’appelle-t-on le style marotique ?', 'mcq', '["Un ton familier, léger, spirituel, avec une pointe finale","Un style grave et solennel","Une écriture obscure et savante","Un langage populaire sans art"]'::jsonb, 0, 'La Fontaine et Voltaire s’en réclameront explicitement.', 5),
    ('fd73ce49-20dd-5a4c-a04f-cfd7a0870328'::uuid, '56fc85ae-6658-5210-b98a-29ad5a14678d'::uuid, 'Marot appartient déjà à la Pléiade.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la précède : c’est un poète de la transition entre Moyen Âge et Renaissance.', 6),
    ('497bdca5-35c1-5564-b4df-5539da1aee26'::uuid, '07b6c9ff-c54f-5431-9513-e2fe1c5f278c'::uuid, 'Où se déroule le récit ?', 'mcq', '["En Indochine française, vers 1930","Au Vietnam des années 1960","En Chine continentale","À Paris"]'::jsonb, 0, 'La traversée du Mékong sur un bac ouvre le livre.', 1),
    ('eeced601-619f-530b-98c5-fab787b39efd'::uuid, '07b6c9ff-c54f-5431-9513-e2fe1c5f278c'::uuid, 'Quel âge a la narratrice au début de la liaison ?', 'mcq', '["Quinze ans et demi","Dix-huit ans","Vingt ans","Treize ans"]'::jsonb, 0, 'L’amant chinois a douze ans de plus qu’elle.', 2),
    ('3df6c730-7ce7-5f9f-b243-0a53d730681f'::uuid, '07b6c9ff-c54f-5431-9513-e2fe1c5f278c'::uuid, 'Quelle image ouvre le livre ?', 'mcq', '["Une photographie jamais prise, celle de la traversée du bac","Un portrait de famille","Une carte de l’Indochine","Une photo de mariage"]'::jsonb, 0, 'C’est cette absence qui autorise le récit.', 3),
    ('fc03f8f1-48a1-5a56-9be8-16e20d5e7b45'::uuid, '07b6c9ff-c54f-5431-9513-e2fe1c5f278c'::uuid, 'Quel prix le livre a-t-il reçu ?', 'mcq', '["Le prix Goncourt 1984","Le Renaudot","Le prix Femina","Le Médicis"]'::jsonb, 0, 'Il a connu un immense succès international.', 4),
    ('b29bbe9a-5f8f-57fa-8e50-4a63c87fc4b6'::uuid, '07b6c9ff-c54f-5431-9513-e2fe1c5f278c'::uuid, 'Comment la famille se comporte-t-elle face à la liaison ?', 'mcq', '["Elle accepte l’argent du Chinois tout en l’humiliant","Elle l’ignore complètement","Elle s’y oppose violemment","Elle encourage le mariage"]'::jsonb, 0, 'La mère est ruinée, le frère aîné violent.', 5),
    ('de9e3ad2-3709-59ac-9320-640261d743dc'::uuid, '07b6c9ff-c54f-5431-9513-e2fe1c5f278c'::uuid, 'Le récit suit une chronologie stricte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est éclaté : alternance du « je » et du « elle », répétitions, blancs.', 6),
    ('82456887-f1f6-50f3-8c77-736c9d723e5b'::uuid, 'f001977a-a7e3-5c4c-8317-fd5c74cd7440'::uuid, 'Qui est Aristide Saccard ?', 'mcq', '["Un spéculateur qui fonde la Banque universelle","Un banquier suisse","Un journaliste financier","Un industriel du textile"]'::jsonb, 0, 'On l’a déjà rencontré dans La Curée.', 1),
    ('cdd76b9b-f98c-52fa-99dd-97cc0e03a1f1'::uuid, 'f001977a-a7e3-5c4c-8317-fd5c74cd7440'::uuid, 'Quel événement réel a inspiré le roman ?', 'mcq', '["Le krach de l’Union générale, en 1882","La crise de 1929","Le scandale de Panama","La faillite du Crédit lyonnais"]'::jsonb, 0, 'Zola s’est documenté avec précision sur les mécanismes boursiers.', 2),
    ('c568de8b-cef7-543a-ae02-1b3ff34c995e'::uuid, 'f001977a-a7e3-5c4c-8317-fd5c74cd7440'::uuid, 'Qui est Gundermann ?', 'mcq', '["Le grand banquier rival, froid et méthodique","Le comptable de Saccard","Un journaliste","Un ministre"]'::jsonb, 0, 'Il attend, et il gagne.', 3),
    ('93ad4a17-a9d1-5a3d-ae48-24678bb7541d'::uuid, 'f001977a-a7e3-5c4c-8317-fd5c74cd7440'::uuid, 'Que provoque l’effondrement du cours ?', 'mcq', '["La ruine générale, des suicides et un procès","Une révolution","La faillite de l’État","Le départ de Saccard à l’étranger uniquement"]'::jsonb, 0, 'Les petits épargnants sont les premières victimes.', 4),
    ('8e5692fd-58be-5056-a166-e837ff8a6807'::uuid, 'f001977a-a7e3-5c4c-8317-fd5c74cd7440'::uuid, 'Quelle vision de l’argent Zola propose-t-il ?', 'mcq', '["Une force ambivalente, destructrice et fécondante","Un mal absolu","Un bien nécessaire","Un sujet indifférent"]'::jsonb, 0, '« Le fumier dans lequel poussait l’humanité de demain. »', 5),
    ('e6dd9048-42c2-57ab-8374-a13e95a78840'::uuid, 'f001977a-a7e3-5c4c-8317-fd5c74cd7440'::uuid, 'Saccard est définitivement anéanti à la fin du roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Condamné, il repart ailleurs : c’est une force que rien n’arrête.', 6),
    ('54011308-35c3-581f-a75c-5bb34c7e87da'::uuid, 'a159d04f-d9be-5b02-a2e4-fb5552333080'::uuid, 'Quelle forme prend L’Art poétique ?', 'mcq', '["Un poème didactique en quatre chants, en alexandrins","Un traité en prose","Un dialogue","Une préface de théâtre"]'::jsonb, 0, 'Sur le modèle de l’Art poétique d’Horace.', 1),
    ('00c33e39-163f-566d-b03f-4549ffae8d51'::uuid, 'a159d04f-d9be-5b02-a2e4-fb5552333080'::uuid, 'Quel précepte concerne la clarté ?', 'mcq', '["« Ce que l’on conçoit bien s’énonce clairement »","« Le beau est toujours bizarre »","« Il faut être absolument moderne »","« Rien de trop »"]'::jsonb, 0, 'La clarté est la vertu cardinale du classicisme.', 2),
    ('22517462-d0ee-5c97-a115-02804b74e6d8'::uuid, 'a159d04f-d9be-5b02-a2e4-fb5552333080'::uuid, 'Quel conseil Boileau donne-t-il sur le travail ?', 'mcq', '["« Vingt fois sur le métier remettez votre ouvrage »","« Écrivez d’un seul jet »","« Suivez votre inspiration »","« Imitez sans corriger »"]'::jsonb, 0, 'L’inspiration ne dispense jamais du travail.', 3),
    ('c1e86590-aca6-566e-9f1b-dc3d3c3908d3'::uuid, 'a159d04f-d9be-5b02-a2e4-fb5552333080'::uuid, 'Quelle règle du théâtre le chant III expose-t-il ?', 'mcq', '["La règle des trois unités","La règle du chœur","L’unité de registre","La division en cinq actes seulement"]'::jsonb, 0, 'Avec la bienséance, elle organise la tragédie classique.', 4),
    ('f6cb36fa-7b87-5bfb-9b41-502e6a120617'::uuid, 'a159d04f-d9be-5b02-a2e4-fb5552333080'::uuid, 'Boileau invente-t-il le classicisme ?', 'mcq', '["Non, il le formule après que Racine et Molière l’ont pratiqué","Oui, il le crée entièrement","Non, il le combat","Oui, avant tous les autres"]'::jsonb, 0, 'Il en est le codificateur, pas l’inventeur.', 5),
    ('850fe72e-007f-543d-b94d-89177c1a8c4a'::uuid, 'a159d04f-d9be-5b02-a2e4-fb5552333080'::uuid, 'Les romantiques ont admiré Boileau.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils l’ont violemment rejeté : Hugo l’appelait « le pédant ».', 6),
    ('105eb210-7cc4-5be5-8c3c-8d2f39890f61'::uuid, '9219a4b7-3857-5973-ac0e-e5c04555504c'::uuid, 'Quel est le métier de Gervaise ?', 'mcq', '["Blanchisseuse","Couturière","Ouvrière en usine","Marchande des quatre-saisons"]'::jsonb, 0, 'Elle ouvre sa propre boutique avant la chute.', 1),
    ('ddee97ff-a073-50b8-b3a6-23895297fef4'::uuid, '9219a4b7-3857-5973-ac0e-e5c04555504c'::uuid, 'Qu’est-ce que l’Assommoir ?', 'mcq', '["Le débit de boisson du père Colombe","L’atelier de zinguerie","L’hôpital Sainte-Anne","L’immeuble de la Goutte-d’Or"]'::jsonb, 0, 'Le titre désigne le lieu qui assomme le quartier.', 2),
    ('95bd4a0e-bb4e-51df-a5a2-49f170ab8c91'::uuid, '9219a4b7-3857-5973-ac0e-e5c04555504c'::uuid, 'Quel événement déclenche la chute du ménage ?', 'mcq', '["La chute de Coupeau d’un toit","La faillite de la boutique","Le retour de Lantier","La naissance de Nana"]'::jsonb, 0, 'Il ne reprend jamais le travail et se met à boire.', 3),
    ('29e2d9f8-e89a-5171-94a5-fde2c25ec9d6'::uuid, '9219a4b7-3857-5973-ac0e-e5c04555504c'::uuid, 'Quelle est la grande nouveauté stylistique du roman ?', 'mcq', '["Le langage populaire passe dans la narration, pas seulement dans les dialogues","L’absence de descriptions","Le récit à la première personne","Le refus du discours indirect"]'::jsonb, 0, 'Le style indirect libre y est généralisé.', 4),
    ('f96c3f02-5b0a-5396-b19c-656b3a068835'::uuid, '9219a4b7-3857-5973-ac0e-e5c04555504c'::uuid, 'Comment Gervaise meurt-elle ?', 'mcq', '["De misère, sous un escalier","À l’hôpital","Assassinée par Coupeau","En couches"]'::jsonb, 0, 'Coupeau meurt de delirium tremens à Sainte-Anne.', 5),
    ('8e634a16-3f8d-53fc-97ae-91c41d5f27cb'::uuid, '9219a4b7-3857-5973-ac0e-e5c04555504c'::uuid, 'Le roman fut aussitôt salué par la critique comme un hommage au peuple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On reprocha à Zola de salir le peuple : le livre fit scandale.', 6),
    ('a3a40852-e5c8-5a9d-b047-192ea0a3d8bb'::uuid, 'b87166ca-cb88-5d72-9248-102ded01c040'::uuid, 'Que cache Harpagon dans son jardin ?', 'mcq', '["Une cassette de dix mille écus","Des titres de propriété","Des bijoux de sa femme","Un testament"]'::jsonb, 0, 'Son vol déclenche la crise finale.', 1),
    ('1a2f28cf-315d-5560-86d6-4eac5540ecdb'::uuid, 'b87166ca-cb88-5d72-9248-102ded01c040'::uuid, 'Pourquoi Harpagon veut-il marier Élise au vieil Anselme ?', 'mcq', '["Parce qu’il la prend « sans dot »","Parce qu’Anselme est noble","Pour se venger de Valère","Parce qu’elle le demande"]'::jsonb, 0, 'La répétition de « sans dot » est un ressort comique majeur.', 2),
    ('ad660973-423a-58b4-8dfc-f1bc7ec154d9'::uuid, 'b87166ca-cb88-5d72-9248-102ded01c040'::uuid, 'Qui vole la cassette ?', 'mcq', '["La Flèche, valet de Cléante","Valère","Maître Jacques","Anselme"]'::jsonb, 0, 'Le vol met Harpagon hors de lui.', 3),
    ('13045b66-8dad-59da-b4de-12bd646166ef'::uuid, 'b87166ca-cb88-5d72-9248-102ded01c040'::uuid, 'De quelle pièce antique Molière s’inspire-t-il ?', 'mcq', '["L’Aulularia de Plaute","Les Guêpes d’Aristophane","Amphitryon de Térence","Les Bacchantes d’Euripide"]'::jsonb, 0, 'La Marmite, en français.', 4),
    ('6a0ce418-ce87-5dd1-a379-9fd761b1d8ac'::uuid, 'b87166ca-cb88-5d72-9248-102ded01c040'::uuid, 'Comment le dénouement s’opère-t-il ?', 'mcq', '["Anselme se révèle être le père perdu de Valère et de Mariane","Harpagon renonce à son argent","Cléante s’enfuit avec Mariane","Élise entre au couvent"]'::jsonb, 0, 'Invraisemblance assumée : Harpagon ne veut que sa cassette.', 5),
    ('6b7a0479-dbd2-5814-911b-3d93c735638d'::uuid, 'b87166ca-cb88-5d72-9248-102ded01c040'::uuid, 'La pièce est écrite en vers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est en prose, ce qui fut reproché à Molière à sa création.', 6),
    ('0724afb5-4743-5785-9186-13b99788b9ed'::uuid, '0ea993b8-7166-5b5d-8afa-902d44c84539'::uuid, 'De quoi Chloé tombe-t-elle malade ?', 'mcq', '["Un nénuphar pousse dans son poumon","D’une pneumonie ordinaire","D’un cancer","D’une allergie aux fleurs"]'::jsonb, 0, 'Seules les fleurs autour d’elle la soulagent.', 1),
    ('36ca33d0-1d5a-53f9-a91d-43545f25b148'::uuid, '0ea993b8-7166-5b5d-8afa-902d44c84539'::uuid, 'Qu’est-ce que le pianocktail ?', 'mcq', '["Un piano qui fabrique des cocktails d’après la musique jouée","Un bar de jazz","Un instrument imaginaire de Chloé","Un jeu de société"]'::jsonb, 0, 'Invention emblématique de la fantaisie de Vian.', 2),
    ('5e5b378c-620e-5d52-8c4a-47264fb342a0'::uuid, '0ea993b8-7166-5b5d-8afa-902d44c84539'::uuid, 'De quel philosophe Chick est-il le collectionneur obsessionnel ?', 'mcq', '["Jean-Sol Partre","Albert Camus","Simone de Beauvoir","Henri Bergson"]'::jsonb, 0, 'Anagramme transparente de Jean-Paul Sartre.', 3),
    ('fed4a881-5afe-5e43-a034-b665f3c3bcb6'::uuid, '0ea993b8-7166-5b5d-8afa-902d44c84539'::uuid, 'Que devient l’appartement au fil du roman ?', 'mcq', '["Il rétrécit et s’assombrit à mesure que Chloé décline","Il s’agrandit","Il est vendu","Il prend feu"]'::jsonb, 0, 'Le décor épouse la maladie : la forme dit le fond.', 4),
    ('57da39e7-0917-5b01-941a-c80b46786f57'::uuid, '0ea993b8-7166-5b5d-8afa-902d44c84539'::uuid, 'Que doit faire Colin pour payer les fleurs ?', 'mcq', '["Travailler, dans des métiers absurdes et cruels","Vendre le pianocktail seulement","Emprunter à Chick","Voler"]'::jsonb, 0, 'La satire du travail est l’une des cibles du livre.', 5),
    ('bed742d0-13cb-51e2-b47a-dcae2059e46f'::uuid, '0ea993b8-7166-5b5d-8afa-902d44c84539'::uuid, 'Le roman fut un succès immédiat à sa parution.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il fut d’abord ignoré, et n’est devenu culte qu’à partir des années 1960.', 6),
    ('7da8a0d2-a7c6-56a0-b5ea-6ba821bb1655'::uuid, '231a1d05-8b32-5da5-8fb0-f784280b6216'::uuid, 'Qui Frédéric Moreau aime-t-il toute sa vie ?', 'mcq', '["Madame Arnoux","Rosanette","Madame Dambreuse","Louise Roque"]'::jsonb, 0, 'Le coup de foudre initial ne débouche jamais sur rien.', 1),
    ('ab3f507d-6470-52b5-baeb-79df9eb5953f'::uuid, '231a1d05-8b32-5da5-8fb0-f784280b6216'::uuid, 'Quel événement historique traverse le roman ?', 'mcq', '["La révolution de 1848 et ses suites","La Commune de 1871","La Révolution de 1789","La guerre de 1870 seule"]'::jsonb, 0, 'Frédéric la traverse sans jamais s’y engager vraiment.', 2),
    ('d15f6499-a7b4-5f1f-a819-14572efde0da'::uuid, '231a1d05-8b32-5da5-8fb0-f784280b6216'::uuid, 'Que réalise Frédéric de ses nombreux projets ?', 'mcq', '["Rien : il n’achève ni livre, ni tableau, ni carrière","Un roman célèbre","Une carrière politique","Une collection d’art"]'::jsonb, 0, 'C’est le roman de l’inachèvement.', 3),
    ('695c6883-0385-53ac-b4f1-9342ebd0ca2b'::uuid, '231a1d05-8b32-5da5-8fb0-f784280b6216'::uuid, 'Sur quoi le roman se termine-t-il ?', 'mcq', '["Le souvenir d’une visite ratée au bordel, « ce que nous avons eu de meilleur »","La mort de Madame Arnoux","Le mariage de Frédéric","Un duel"]'::jsonb, 0, 'La dérision est totale, et bouleversante.', 4),
    ('04ae80a2-d356-59af-ad05-d763fd55a35d'::uuid, '231a1d05-8b32-5da5-8fb0-f784280b6216'::uuid, 'Quelle phrase célèbre marque une ellipse de plusieurs années ?', 'mcq', '["« Il voyagea »","« Il attendit »","« Le temps passa »","« Rien n’arriva »"]'::jsonb, 0, 'Deux mots pour effacer des années entières.', 5),
    ('8c3e2f30-aa68-5133-bfd5-b635dc6c07a2'::uuid, '231a1d05-8b32-5da5-8fb0-f784280b6216'::uuid, 'Le roman fut un grand succès à sa parution.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il fut mal reçu en 1869, et n’est devenu central qu’au XXe siècle.', 6),
    ('3ab3f2f2-d962-5e7b-9930-98d430c80e50'::uuid, 'dbe9cdfa-4b81-5d48-b868-e6cb701c6ad1'::uuid, 'Qui prononce le discours de L’Éloge de la folie ?', 'mcq', '["La Folie elle-même","Érasme en son nom","Thomas More","Un moine anonyme"]'::jsonb, 0, 'Le procédé permet de tout dire sous le masque.', 1),
    ('5099f0af-3ffd-5f29-847a-689dfff2ac65'::uuid, 'dbe9cdfa-4b81-5d48-b868-e6cb701c6ad1'::uuid, 'À qui l’œuvre est-elle dédiée ?', 'mcq', '["À Thomas More","À Luther","Au pape Léon X","À Charles Quint"]'::jsonb, 0, 'Le titre latin, Moriae encomium, joue sur son nom.', 2),
    ('7db4ee30-fbe6-5b0c-ad2d-98d8eb5c3bfa'::uuid, 'dbe9cdfa-4b81-5d48-b868-e6cb701c6ad1'::uuid, 'Comment le ton évolue-t-il au fil du texte ?', 'mcq', '["Du badinage à la satire de plus en plus dure","De la colère à la douceur","Il reste badin du début à la fin","Il est uniformément savant"]'::jsonb, 0, 'Grammairiens, théologiens, moines, princes et papes y passent.', 3),
    ('4dc727f0-23f6-5902-9300-59aa71b61c4a'::uuid, 'dbe9cdfa-4b81-5d48-b868-e6cb701c6ad1'::uuid, 'Quel retournement clôt l’ouvrage ?', 'mcq', '["La vraie folie est celle de la foi, sagesse devant Dieu","La Folie avoue avoir menti","La Raison prend la parole","Le texte s’interrompt sans conclusion"]'::jsonb, 0, 'C’est la folie de saint Paul et du Christ.', 4),
    ('7177929b-7d82-5943-9878-3553db0714c8'::uuid, 'dbe9cdfa-4b81-5d48-b868-e6cb701c6ad1'::uuid, 'Quelle est la position d’Érasme envers l’Église ?', 'mcq', '["Il la critique de l’intérieur, sans rompre","Il la quitte pour la Réforme","Il la défend sans réserve","Il l’ignore"]'::jsonb, 0, 'Il polémiquera d’ailleurs avec Luther.', 5),
    ('ab7cd85b-8353-55bb-b688-2b47d6e321ed'::uuid, 'dbe9cdfa-4b81-5d48-b868-e6cb701c6ad1'::uuid, 'L’œuvre a été écrite en français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est écrite en latin, langue commune des humanistes européens.', 6),
    ('cd13690c-4b04-54e3-bfef-e3d96ec2c1e0'::uuid, 'acd8d1da-64f4-56a4-a1e5-a1634f2a22da'::uuid, 'Qui mène l’enquête dans le récit ?', 'mcq', '["Le notaire Utterson","La police de Londres","Le docteur Lanyon seul","Jekyll lui-même"]'::jsonb, 0, 'Le lecteur découvre les faits avant l’explication.', 1),
    ('13cf2232-a2a2-5878-876e-38f8d0184605'::uuid, 'acd8d1da-64f4-56a4-a1e5-a1634f2a22da'::uuid, 'Quel est le projet initial de Jekyll ?', 'mcq', '["Séparer chimiquement le bien et le mal en lui","Rajeunir","Guérir une maladie","Devenir invisible"]'::jsonb, 0, 'La potion lui permet de devenir Hyde.', 2),
    ('1663c9e3-b723-535f-9250-51804a36a343'::uuid, 'acd8d1da-64f4-56a4-a1e5-a1634f2a22da'::uuid, 'Que se passe-t-il à mesure que le récit avance ?', 'mcq', '["Les transformations deviennent involontaires","Hyde disparaît","Jekyll retrouve la maîtrise","La potion cesse d’agir"]'::jsonb, 0, 'Hyde prend progressivement le dessus.', 3),
    ('10104997-ff48-5e9c-b0b9-31618aaa5b75'::uuid, 'acd8d1da-64f4-56a4-a1e5-a1634f2a22da'::uuid, 'Comment le récit se termine-t-il ?', 'mcq', '["Jekyll s’enferme et se suicide","Hyde est arrêté","Jekyll guérit","Utterson découvre l’antidote"]'::jsonb, 0, 'Il n’a plus l’ingrédient nécessaire à la transformation inverse.', 4),
    ('499aed61-9372-51ca-b2a8-83579d594348'::uuid, 'acd8d1da-64f4-56a4-a1e5-a1634f2a22da'::uuid, 'Que dénonce le récit dans la société victorienne ?', 'mcq', '["L’hypocrisie de la respectabilité de façade","La pauvreté des faubourgs","La corruption politique","Le poids de l’Église"]'::jsonb, 0, 'La respectabilité exige une part cachée.', 5),
    ('44d20d5c-2441-5588-89dd-66bd512a2766'::uuid, 'acd8d1da-64f4-56a4-a1e5-a1634f2a22da'::uuid, 'Le récit dévoile l’explication dès les premières pages.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est construit comme une enquête : la vérité arrive par documents, à la fin.', 6),
    ('172929d0-394a-55aa-bfc9-ca30b88c4466'::uuid, '90337329-6bfa-5081-be92-1e7f664852b5'::uuid, 'Par quelle phrase le roman commence-t-il ?', 'mcq', '["« Aujourd’hui, maman est morte »","« Il faisait très chaud »","« Je m’appelle Meursault »","« Le soleil était insoutenable »"]'::jsonb, 0, 'Le ton neutre est donné dès la première ligne.', 1),
    ('34f5d341-bd09-5802-85fb-8698ea14f6fa'::uuid, '90337329-6bfa-5081-be92-1e7f664852b5'::uuid, 'Que reproche-t-on surtout à Meursault lors du procès ?', 'mcq', '["De n’avoir pas pleuré à l’enterrement de sa mère","D’avoir prémédité le meurtre","D’avoir menti à la police","D’avoir fui"]'::jsonb, 0, 'Il est jugé pour son indifférence plus que pour son crime.', 2),
    ('56fbce63-b7a3-5627-b178-9b954be18815'::uuid, '90337329-6bfa-5081-be92-1e7f664852b5'::uuid, 'Où et dans quelles circonstances le meurtre a-t-il lieu ?', 'mcq', '["Sur une plage écrasée de soleil","Dans un bar la nuit","Chez Raymond","Au cimetière"]'::jsonb, 0, 'Le soleil est présenté comme un élément déterminant.', 3),
    ('0f72ba8e-b38f-5f19-9e9e-7c67d5864a70'::uuid, '90337329-6bfa-5081-be92-1e7f664852b5'::uuid, 'Comment appelle-t-on le style du roman ?', 'mcq', '["L’écriture blanche","Le style flamboyant","Le réalisme lyrique","L’écriture artiste"]'::jsonb, 0, 'Phrases courtes, passé composé, neutralité : Barthes l’a analysée.', 4),
    ('d4402d49-21e7-51fb-92ec-2caa258bc8c4'::uuid, '90337329-6bfa-5081-be92-1e7f664852b5'::uuid, 'Comment Meursault réagit-il face à l’aumônier ?', 'mcq', '["Il refuse ses consolations et explose de colère","Il se convertit","Il l’ignore poliment","Il demande le pardon"]'::jsonb, 0, 'Puis il accède à « la tendre indifférence du monde ».', 5),
    ('226e89fa-d3bb-5f0f-af66-69b09d30e5da'::uuid, '90337329-6bfa-5081-be92-1e7f664852b5'::uuid, 'Meursault est un personnage insensible et sans émotion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il refuse de mentir sur ce qu’il ressent : c’est ce refus que la société condamne.', 6),
    ('a7d09550-acfa-5334-ad83-872d255700ca'::uuid, '74e18a1c-a094-57d1-97c3-2692f6fc03ed'::uuid, 'Quelle distinction fonde l’ouvrage ?', 'mcq', '["L’en-soi (les choses) et le pour-soi (la conscience)","Le corps et l’âme","Le bien et le mal","La nature et la culture"]'::jsonb, 0, 'Le pour-soi n’est jamais ce qu’il est : il est en projet.', 1),
    ('a373afc7-fb01-59f4-8729-a35c76b84467'::uuid, '74e18a1c-a094-57d1-97c3-2692f6fc03ed'::uuid, 'Que signifie « l’existence précède l’essence » ?', 'mcq', '["L’homme n’a pas de nature préalable : il se définit par ses actes","L’âme existe avant le corps","La matière précède l’esprit","La société détermine l’individu"]'::jsonb, 0, 'C’est la formule centrale de l’existentialisme sartrien.', 2),
    ('32c02eca-8f48-59d2-8610-4cb1bb015741'::uuid, '74e18a1c-a094-57d1-97c3-2692f6fc03ed'::uuid, 'Qu’est-ce que la mauvaise foi ?', 'mcq', '["Se mentir à soi-même pour fuir sa liberté","Mentir aux autres","Renier ses engagements politiques","Refuser la religion"]'::jsonb, 0, 'Le garçon de café qui « joue » son rôle en est l’exemple célèbre.', 3),
    ('0b783e70-c5e4-504e-b3a1-93412b612d91'::uuid, '74e18a1c-a094-57d1-97c3-2692f6fc03ed'::uuid, 'Quel effet le regard d’autrui produit-il ?', 'mcq', '["Il me fige en objet","Il me libère","Il n’a aucun effet","Il me révèle ma nature"]'::jsonb, 0, 'C’est le point de départ du conflit des consciences, mis en scène dans Huis clos.', 4),
    ('04619aef-3c5c-5fa6-9533-e32a49d2d4a4'::uuid, '74e18a1c-a094-57d1-97c3-2692f6fc03ed'::uuid, 'Quel texte donne une version accessible de cette philosophie ?', 'mcq', '["L’existentialisme est un humanisme (1946)","La Nausée","Les Mots","Situations I"]'::jsonb, 0, 'C’est une conférence, publiée l’année suivante.', 5),
    ('9b0d1c7b-9b1e-5ba0-8cfe-d7e6d53785e5'::uuid, '74e18a1c-a094-57d1-97c3-2692f6fc03ed'::uuid, 'Selon Sartre, la liberté est limitée par une nature humaine donnée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’y a pas de nature humaine préalable : « l’homme est condamné à être libre ».', 6),
    ('0ac19484-09b4-5f64-950e-741a58882acf'::uuid, 'abc9c0f4-170a-57b6-a2d6-369723524d15'::uuid, 'Pourquoi Gwynplaine rit-il perpétuellement ?', 'mcq', '["Son visage a été taillé par des comprachicos","Il est atteint d’une maladie nerveuse","C’est un masque de scène","Il a choisi ce rôle"]'::jsonb, 0, 'Ils mutilaient les enfants pour en faire des monstres de foire.', 1),
    ('b7d8bf4c-2354-57b3-85a2-e021799fbf53'::uuid, 'abc9c0f4-170a-57b6-a2d6-369723524d15'::uuid, 'Qui sont Dea, Ursus et Homo ?', 'mcq', '["Une jeune aveugle, le forain qui les recueille et son loup","Trois enfants perdus","Des lords anglais","Les parents de Gwynplaine"]'::jsonb, 0, 'Ils forment la famille de substitution du héros.', 2),
    ('17a87541-1b8d-5dcd-ace9-404993a78168'::uuid, 'abc9c0f4-170a-57b6-a2d6-369723524d15'::uuid, 'Que se passe-t-il à la Chambre des lords ?', 'mcq', '["Gwynplaine plaide pour le peuple, et les lords rient de son visage","Il est acclamé","Il est chassé sans parler","Il refuse de siéger"]'::jsonb, 0, 'Le peuple, quoi qu’il dise, fait rire ceux qui le dominent.', 3),
    ('4862056c-973e-5ee6-9fb2-cba4d5398b6a'::uuid, 'abc9c0f4-170a-57b6-a2d6-369723524d15'::uuid, 'Quelle est la véritable identité de Gwynplaine ?', 'mcq', '["Lord Clancharlie","Le fils d’Ursus","Un prince français","Un bâtard royal"]'::jsonb, 0, 'Un document retrouvé révèle sa naissance.', 4),
    ('5b8e513d-b831-56ee-b483-3d154a6a0805'::uuid, 'abc9c0f4-170a-57b6-a2d6-369723524d15'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Dea meurt, et Gwynplaine se jette à la mer","Gwynplaine devient lord et épouse Dea","Ursus adopte Gwynplaine officiellement","Gwynplaine se venge des comprachicos"]'::jsonb, 0, 'La fin est parmi les plus sombres de Hugo.', 5),
    ('82556808-b805-5e57-bcc3-6aa6e2055525'::uuid, 'abc9c0f4-170a-57b6-a2d6-369723524d15'::uuid, 'Le roman fut un succès immédiat.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il fut mal reçu en 1869, et n’a été relu et apprécié que bien plus tard.', 6),
    ('08213c5d-ac7d-59bc-bdc7-d8c1629eb106'::uuid, '46e68ba6-9a81-5f87-98b8-26de4164294b'::uuid, 'Quelle est la loi de l’île ?', 'mcq', '["Maîtres et serviteurs échangent conditions et habits pour trois ans","Les maîtres sont exécutés","Les esclaves sont libérés puis renvoyés","Tout le monde devient égal définitivement"]'::jsonb, 0, 'L’échange doit servir à corriger les maîtres.', 1),
    ('5c7dfcb4-753c-51b2-9b6e-613bbafe61da'::uuid, '46e68ba6-9a81-5f87-98b8-26de4164294b'::uuid, 'Qui applique cette loi ?', 'mcq', '["Trivelin, le gouverneur de l’île","Arlequin","Iphicrate","Cléanthis"]'::jsonb, 0, 'L’île est peuplée d’anciens esclaves révoltés.', 2),
    ('cc3a60df-9d6b-584e-ab6d-36b66c5db6f0'::uuid, '46e68ba6-9a81-5f87-98b8-26de4164294b'::uuid, 'Que font Arlequin et Cléanthis quand ils pourraient se venger ?', 'mcq', '["Ils pardonnent","Ils punissent leurs maîtres","Ils s’enfuient","Ils réclament de l’argent"]'::jsonb, 0, 'Le dénouement repose sur leur générosité.', 3),
    ('47a4d191-a0fd-5ee7-979a-4cfaa3fa5433'::uuid, '46e68ba6-9a81-5f87-98b8-26de4164294b'::uuid, 'Quelle est la visée de la pièce ?', 'mcq', '["Rendre les rapports humains, non abolir les conditions","Appeler à la révolution","Défendre l’esclavage antique","Se moquer des serviteurs"]'::jsonb, 0, 'C’est une utopie pédagogique, pas un programme politique.', 4),
    ('2a97593d-e4c3-58d7-b584-89c00103b5c3'::uuid, '46e68ba6-9a81-5f87-98b8-26de4164294b'::uuid, 'D’où naît le comique de la pièce ?', 'mcq', '["Du décalage entre l’habit et la personne","De quiproquos amoureux","De jeux de mots savants","De chutes et de coups"]'::jsonb, 0, 'Les portraits des maîtres par leurs serviteurs sont impitoyables.', 5),
    ('64f0413f-0ff5-5a03-851b-16010ae9ed41'::uuid, '46e68ba6-9a81-5f87-98b8-26de4164294b'::uuid, 'La pièce est en cinq actes et en vers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle tient en un acte et en prose.', 6),
    ('b13fed7d-0e61-545c-b1ed-2e89bd4f5e49'::uuid, '7a2f12ac-2e56-595a-98fe-6fb66cba49ce'::uuid, 'Comment les héros arrivent-ils sur l’île ?', 'mcq', '["En s’évadant en ballon pendant la guerre de Sécession","Par un naufrage","À bord du Nautilus","Par une expédition scientifique"]'::jsonb, 0, 'Ils nomment l’île Lincoln en hommage au président.', 1),
    ('16293022-efa6-5b6d-ad2e-825f64b967dd'::uuid, '7a2f12ac-2e56-595a-98fe-6fb66cba49ce'::uuid, 'Qui est le chef naturel du groupe ?', 'mcq', '["L’ingénieur Cyrus Smith","Le marin Pencroff","Le journaliste Spilett","Nab"]'::jsonb, 0, 'Son savoir permet de reconstruire une civilisation à partir de rien.', 2),
    ('1816b8bf-58b8-544f-8ee9-de06a384841b'::uuid, '7a2f12ac-2e56-595a-98fe-6fb66cba49ce'::uuid, 'Quel personnage protège secrètement les colons ?', 'mcq', '["Le capitaine Nemo","Un naufragé anglais","Un pirate repenti","Un savant américain"]'::jsonb, 0, 'Il est le dernier survivant de Vingt Mille Lieues sous les mers.', 3),
    ('7acffda1-9541-55d0-a19c-8e404d2b5b2b'::uuid, '7a2f12ac-2e56-595a-98fe-6fb66cba49ce'::uuid, 'À quel genre le roman appartient-il ?', 'mcq', '["La robinsonnade scientifique","Le roman policier","Le roman historique","Le conte philosophique"]'::jsonb, 0, 'Le savoir remplace le miracle et la Providence.', 4),
    ('db7f765b-a33b-54c7-9d33-2a0f2d2d9166'::uuid, '7a2f12ac-2e56-595a-98fe-6fb66cba49ce'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["L’île explose et les colons sont sauvés","Les colons restent sur l’île","Nemo emmène les colons","Ils construisent un navire et rentrent seuls"]'::jsonb, 0, 'Le volcan de l’île entre en éruption.', 5),
    ('52d5e95c-de3d-530e-8174-6b72a3eab059'::uuid, '7a2f12ac-2e56-595a-98fe-6fb66cba49ce'::uuid, 'Le roman est indépendant des autres livres de Verne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il forme une trilogie avec Les Enfants du capitaine Grant et Vingt Mille Lieues sous les mers.', 6),
    ('2bc276ba-cfc5-5a2d-a315-a27f1864398e'::uuid, '5911ef52-49ae-5d4e-945f-b884647d51a5'::uuid, 'Que demande Pridamant au magicien Alcandre ?', 'mcq', '["De lui montrer ce qu’est devenu son fils Clindor","De lui rendre sa jeunesse","De punir son fils","De lui prédire l’avenir"]'::jsonb, 0, 'Alcandre fait apparaître des scènes dans sa grotte.', 1),
    ('30dde28c-8523-5761-9492-2ca1b8b30280'::uuid, '5911ef52-49ae-5d4e-945f-b884647d51a5'::uuid, 'Qui est Matamore ?', 'mcq', '["Un fanfaron dont Clindor est le valet","Le père d’Isabelle","Un magicien rival","Un comédien de la troupe"]'::jsonb, 0, 'Personnage hérité de la comédie espagnole.', 2),
    ('e589b0e5-8471-5ce8-a7b1-c45b7635cc35'::uuid, '5911ef52-49ae-5d4e-945f-b884647d51a5'::uuid, 'Que découvre-t-on à la fin de la pièce ?', 'mcq', '["Le dernier meurtre était une scène de théâtre : Clindor est comédien","Clindor est mort pour de bon","Alcandre avait menti depuis le début","Pridamant rêvait"]'::jsonb, 0, 'Le rideau tiré révèle des comédiens qui comptent leur recette.', 3),
    ('6683a647-76c3-5f2b-91aa-635a18e2876b'::uuid, '5911ef52-49ae-5d4e-945f-b884647d51a5'::uuid, 'Quel procédé structure la pièce ?', 'mcq', '["La mise en abyme : du théâtre dans du théâtre","Le monologue continu","Le récit épistolaire","Le chœur antique"]'::jsonb, 0, 'Avec un spectateur intérieur, Pridamant.', 4),
    ('9e63f512-79b6-53aa-9702-6db5db72b494'::uuid, '5911ef52-49ae-5d4e-945f-b884647d51a5'::uuid, 'Quelle est la visée de la pièce ?', 'mcq', '["Défendre le théâtre et le métier de comédien","Dénoncer l’illusion théâtrale","Célébrer la magie","Critiquer les pères autoritaires"]'::jsonb, 0, 'Le métier de comédien était alors méprisé et excommunié.', 5),
    ('44167182-3118-596a-a54d-b75724414fc6'::uuid, '5911ef52-49ae-5d4e-945f-b884647d51a5'::uuid, 'Corneille jugeait sa pièce parfaitement régulière.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’appelait lui-même « un étrange monstre ».', 6),
    ('3d4c0f27-d4dd-5b93-b076-d58d0acd0ab6'::uuid, '3dabc8f5-d117-579e-afc7-d7409a092845'::uuid, 'Qu’est-ce qui transforme Michel ?', 'mcq', '["Sa guérison de la tuberculose en Tunisie","La mort de son père","Un héritage","La lecture de Nietzsche"]'::jsonb, 0, 'Il découvre son corps, le soleil et la sensualité.', 1),
    ('d4ee4aa8-4ac8-5c86-8087-92c7773b1f13'::uuid, '3dabc8f5-d117-579e-afc7-d7409a092845'::uuid, 'Que devient Marceline ?', 'mcq', '["Elle tombe malade et meurt lors d’un voyage vers le sud","Elle quitte Michel","Elle guérit et l’accompagne","Elle entre au couvent"]'::jsonb, 0, 'La liberté de Michel se paie de sa mort.', 2),
    ('ec5fb37c-9837-5ad8-a492-7477516f9fed'::uuid, '3dabc8f5-d117-579e-afc7-d7409a092845'::uuid, 'Que signifie « immoralisme » chez Gide ?', 'mcq', '["Le refus des valeurs reçues, non l’absence de morale","La défense du crime","L’athéisme militant","L’indifférence au bien et au mal"]'::jsonb, 0, 'La préface met en garde : le livre est un « fruit plein de cendre amère ».', 3),
    ('c63231f6-5341-5968-a19e-784f35698cfa'::uuid, '3dabc8f5-d117-579e-afc7-d7409a092845'::uuid, 'À qui Michel raconte-t-il son histoire ?', 'mcq', '["À trois amis venus le retrouver en Algérie","À un prêtre","Dans un journal intime","À un médecin"]'::jsonb, 0, 'Le récit est encadré par cette confession.', 4),
    ('43de5d77-a3f6-52b6-8a4f-f3cfb5ed1f69'::uuid, '3dabc8f5-d117-579e-afc7-d7409a092845'::uuid, 'Quel autre récit de Gide traite l’excès inverse ?', 'mcq', '["La Porte étroite, sur le renoncement","Les Faux-Monnayeurs","Les Caves du Vatican","Si le grain ne meurt"]'::jsonb, 0, 'Les deux livres se répondent comme deux excès symétriques.', 5),
    ('17726b86-b6b5-50e4-b1d7-64ce908496c4'::uuid, '3dabc8f5-d117-579e-afc7-d7409a092845'::uuid, 'Gide approuve entièrement la conduite de son personnage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le récit expose sans absoudre : la libération de Michel détruit autour de lui.', 6),
    ('6d2cde6d-de5f-543e-a9b5-6941ea73d1f9'::uuid, '2d823806-50df-519b-b739-6a018f91d3b3'::uuid, 'Qui est l’Ingénu ?', 'mcq', '["Un jeune Huron qui se révèle neveu du prieur de Kerkabon","Un paysan breton","Un soldat anglais","Un moine défroqué"]'::jsonb, 0, 'Son regard neuf sert d’abord le comique, puis la dénonciation.', 1),
    ('84554884-5f5a-5954-9ec6-cd5f6ccbb373'::uuid, '2d823806-50df-519b-b739-6a018f91d3b3'::uuid, 'Pourquoi l’Ingénu est-il embastillé ?', 'mcq', '["Sur dénonciation, par un ordre arbitraire, après avoir servi le roi","Pour vol","Pour hérésie prouvée","Pour désertion"]'::jsonb, 0, 'Les lettres de cachet sont une cible majeure du conte.', 2),
    ('06750544-2a62-586a-a70a-c0c5cd881399'::uuid, '2d823806-50df-519b-b739-6a018f91d3b3'::uuid, 'Qui instruit l’Ingénu en prison ?', 'mcq', '["Gordon, un vieux janséniste","Un jésuite","Un officier","Le prieur de Kerkabon"]'::jsonb, 0, 'La prison devient paradoxalement un lieu de formation.', 3),
    ('26bea9e6-a8a4-52c8-a005-54464c159f6a'::uuid, '2d823806-50df-519b-b739-6a018f91d3b3'::uuid, 'Comment Mademoiselle de Saint-Yves obtient-elle la libération ?', 'mcq', '["En cédant au sous-ministre Saint-Pouange","En payant une rançon","En s’adressant au roi","Par un procès"]'::jsonb, 0, 'Elle en meurt de honte et de chagrin.', 4),
    ('2bd640e8-fd28-55f5-9627-4e338f1d0ba4'::uuid, '2d823806-50df-519b-b739-6a018f91d3b3'::uuid, 'En quoi ce conte diffère-t-il de Candide ?', 'mcq', '["Le rire y cède progressivement à l’indignation","Il est plus optimiste","Il ne comporte aucune satire","Il se déroule hors de France"]'::jsonb, 0, 'La fin est sans consolation.', 5),
    ('c7bc490d-9fd0-5600-ac21-0ea1b1b6f7cf'::uuid, '2d823806-50df-519b-b739-6a018f91d3b3'::uuid, 'L’Ingénu comprend immédiatement les usages religieux français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il les juge par la logique, ce qui les rend absurdes : c’est le ressort du conte.', 6),
    ('6d8028e6-030c-5574-b70a-14a6f4210262'::uuid, '18c8e0f2-66b3-5fdf-8659-4a35e7428f33'::uuid, 'Quel est le métier de Claude Lantier ?', 'mcq', '["Peintre","Écrivain","Sculpteur","Journaliste"]'::jsonb, 0, 'Il veut imposer une peinture de plein air, lumineuse.', 1),
    ('235d46ee-9fa8-524a-8387-024d218a3b66'::uuid, '18c8e0f2-66b3-5fdf-8659-4a35e7428f33'::uuid, 'Où son grand tableau est-il exposé ?', 'mcq', '["Au Salon des refusés","Au Louvre","Dans une galerie privée","À l’Académie"]'::jsonb, 0, 'Le public en rit : c’est un épisode historique réel.', 2),
    ('a30dab00-7dd3-5219-a517-8521cf5f13e4'::uuid, '18c8e0f2-66b3-5fdf-8659-4a35e7428f33'::uuid, 'Qu’est-ce qui perd Claude ?', 'mcq', '["Un tableau monumental qu’il recommence sans fin","Une dette de jeu","La maladie de Christine","La censure officielle"]'::jsonb, 0, 'Il ne parvient jamais à faire coïncider la toile et sa vision.', 3),
    ('e4415b6b-543f-572b-812d-89c284e13755'::uuid, '18c8e0f2-66b3-5fdf-8659-4a35e7428f33'::uuid, 'Quelle amitié le roman a-t-il brisée ?', 'mcq', '["Celle de Zola et de Paul Cézanne","Celle de Zola et de Manet","Celle de Zola et de Flaubert","Celle de Zola et de Maupassant"]'::jsonb, 0, 'Cézanne s’est en partie reconnu dans Claude Lantier.', 4),
    ('9e53b9a0-7ac8-581d-89e6-4fa84fbad5c1'::uuid, '18c8e0f2-66b3-5fdf-8659-4a35e7428f33'::uuid, 'Que fait Sandoz au cimetière ?', 'mcq', '["Il dit : « Allons travailler »","Il maudit l’art","Il brûle les toiles","Il promet de venger Claude"]'::jsonb, 0, 'Sandoz est le double romanesque de Zola.', 5),
    ('88076817-ef2e-553e-bda9-056fe355de7f'::uuid, '18c8e0f2-66b3-5fdf-8659-4a35e7428f33'::uuid, 'Le roman célèbre la réussite artistique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un roman de l’impuissance créatrice et du prix payé par l’art.', 6),
    ('d782f740-3c52-5deb-a28d-97d4baa072f8'::uuid, '2b3b8f40-95d0-5809-b201-15dfe717698a'::uuid, 'Qui prend la parole dans le poème ?', 'mcq', '["Les pendus eux-mêmes","Le bourreau","Villon en son nom","Dieu"]'::jsonb, 0, '« Frères humains qui après nous vivez. »', 1),
    ('715c3d89-4f0c-5235-93ab-aba35e01ce7b'::uuid, '2b3b8f40-95d0-5809-b201-15dfe717698a'::uuid, 'Dans quelles circonstances le poème aurait-il été écrit ?', 'mcq', '["Alors que Villon était condamné à la pendaison","Après sa libération","Pendant un voyage","À la cour du duc d’Orléans"]'::jsonb, 0, 'La peine fut ensuite commuée en bannissement.', 2),
    ('34d43295-6fc8-5485-bdc0-dde75e76737a'::uuid, '2b3b8f40-95d0-5809-b201-15dfe717698a'::uuid, 'Que demandent les pendus aux vivants ?', 'mcq', '["De ne pas se moquer et de prier Dieu pour eux","De les venger","De les enterrer","De prouver leur innocence"]'::jsonb, 0, '« Priez Dieu que tous nous veuille absoudre ! »', 3),
    ('61f9348b-0a47-5f27-bf99-1ff9da382ba6'::uuid, '2b3b8f40-95d0-5809-b201-15dfe717698a'::uuid, 'Quelle est la forme du poème ?', 'mcq', '["Une ballade : trois huitains et un envoi","Un sonnet","Un rondeau","Une ode"]'::jsonb, 0, 'Forme fixe très pratiquée au XVe siècle.', 4),
    ('2e00ee48-387a-5362-a3ce-f31c463d3994'::uuid, '2b3b8f40-95d0-5809-b201-15dfe717698a'::uuid, 'Quelle esthétique le poème illustre-t-il ?', 'mcq', '["Le macabre médiéval, après la peste et la guerre","Le lyrisme courtois","La poésie pastorale","Le burlesque"]'::jsonb, 0, 'Les corps y sont décrits avec un réalisme cru.', 5),
    ('0972f918-fa09-5533-9293-c68ea1ca7761'::uuid, '2b3b8f40-95d0-5809-b201-15dfe717698a'::uuid, 'On connaît précisément la fin de la vie de Villon.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il disparaît sans trace après 1463 : sa légende a nourri toute la poésie française.', 6),
    ('9500f659-f552-5f37-a80a-1cdebad46f9a'::uuid, '87ee6326-a438-59fc-ad7f-78781005f636'::uuid, 'Pourquoi Roubaud tue-t-il le président Grandmorin ?', 'mcq', '["Parce qu’il apprend que sa femme a été sa maîtresse","Pour de l’argent","Par vengeance politique","Par accident"]'::jsonb, 0, 'Il contraint Séverine à l’attirer dans un train.', 1),
    ('b0f9285d-80d0-558d-a8ca-d8ba59b33064'::uuid, '87ee6326-a438-59fc-ad7f-78781005f636'::uuid, 'De quoi souffre Jacques Lantier ?', 'mcq', '["D’une pulsion héréditaire à tuer les femmes qu’il désire","D’alcoolisme","D’une maladie des poumons","De crises de somnambulisme"]'::jsonb, 0, 'C’est la thèse naturaliste de l’hérédité poussée à l’extrême.', 2),
    ('5673f022-d57c-529b-b451-63a58f82bd5d'::uuid, '87ee6326-a438-59fc-ad7f-78781005f636'::uuid, 'Comment s’appelle la locomotive de Jacques ?', 'mcq', '["La Lison","La Bête","La Séverine","L’Étoile"]'::jsonb, 0, 'Elle est traitée comme un personnage, avec un corps et une agonie.', 3),
    ('2491c912-c7cb-5de6-9ed9-1fe746ef9f9b'::uuid, '87ee6326-a438-59fc-ad7f-78781005f636'::uuid, 'Qui Jacques finit-il par tuer ?', 'mcq', '["Séverine","Roubaud","Cabuche","Pecqueux"]'::jsonb, 0, 'Cabuche sera condamné à sa place.', 4),
    ('f74a8a4d-f590-5b2a-9a3b-d27e6482a5c2'::uuid, '87ee6326-a438-59fc-ad7f-78781005f636'::uuid, 'Quelle est la dernière image du roman ?', 'mcq', '["Un train sans conducteur, plein de soldats, lancé dans la nuit","Un incendie de gare","Un procès","Le suicide de Roubaud"]'::jsonb, 0, 'Les soldats partent pour la guerre de 1870 : l’image est politique.', 5),
    ('a3e7df50-0005-5575-98b9-7555529ba29a'::uuid, '87ee6326-a438-59fc-ad7f-78781005f636'::uuid, 'Le chemin de fer n’est qu’un décor dans le roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La machine est un personnage à part entière, jusque dans son agonie.', 6),
    ('2bb76fde-4326-5e16-86de-1a7cdf4c4941'::uuid, '5eac1d03-7c9d-5230-b9f3-4fcc354af7c8'::uuid, 'Quelle bataille Fabrice traverse-t-il sans la comprendre ?', 'mcq', '["Waterloo","Austerlitz","Marengo","Iéna"]'::jsonb, 0, 'Page modèle du récit de guerre vu d’en bas.', 1),
    ('f8d870df-ee87-5a5f-81d6-a4782e73a2d4'::uuid, '5eac1d03-7c9d-5230-b9f3-4fcc354af7c8'::uuid, 'Qui protège Fabrice à Parme ?', 'mcq', '["Sa tante la duchesse Sanseverina et le comte Mosca","Le prince de Parme","Le général Conti","L’archevêque"]'::jsonb, 0, 'La duchesse l’aime, et Mosca aime la duchesse.', 2),
    ('2b3dc24d-96c1-54fd-9dbc-f7f8ff51d427'::uuid, '5eac1d03-7c9d-5230-b9f3-4fcc354af7c8'::uuid, 'Où Fabrice connaît-il le plus grand bonheur de sa vie ?', 'mcq', '["En prison, dans la tour Farnèse","À Waterloo","Au couvent","À Milan"]'::jsonb, 0, 'Il y aperçoit Clélia Conti depuis sa cellule.', 3),
    ('3f6aa076-e81b-52f1-b046-6634d14a287d'::uuid, '5eac1d03-7c9d-5230-b9f3-4fcc354af7c8'::uuid, 'Quel vœu Clélia a-t-elle prononcé ?', 'mcq', '["Ne plus jamais revoir Fabrice","Ne jamais se marier","Entrer au couvent","Renoncer à son père"]'::jsonb, 0, 'Ils s’aimeront dans l’obscurité, pour ne pas se voir.', 4),
    ('30d8a225-1fdf-53b5-a063-018a2f6e65a0'::uuid, '5eac1d03-7c9d-5230-b9f3-4fcc354af7c8'::uuid, 'En combien de temps Stendhal a-t-il écrit le roman ?', 'mcq', '["Cinquante-deux jours","Deux ans","Cinq ans","Six mois"]'::jsonb, 0, 'La rapidité de la dictée se sent dans le rythme du livre.', 5),
    ('42288c34-e5a1-56d1-8c8b-b76703b9dc84'::uuid, '5eac1d03-7c9d-5230-b9f3-4fcc354af7c8'::uuid, 'La prison est décrite comme un lieu de malheur absolu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est paradoxalement le lieu du bonheur le plus intense de Fabrice.', 6),
    ('4c070366-1281-5fce-a8b0-e7f9235dce05'::uuid, '3225be99-cfa5-52f4-b4cd-3de075a672f9'::uuid, 'Combien de romans et nouvelles La Comédie humaine compte-t-elle ?', 'mcq', '["Environ quatre-vingt-dix achevés","Une vingtaine","Deux cents","Cinquante exactement"]'::jsonb, 0, 'Sur cent trente-sept prévus, avec plus de deux mille personnages.', 1),
    ('c9095e7a-50fa-599b-91a7-1a99a0564d6e'::uuid, '3225be99-cfa5-52f4-b4cd-3de075a672f9'::uuid, 'À quelle œuvre le titre répond-il ?', 'mcq', '["La Divine Comédie de Dante","L’Iliade","Les Essais de Montaigne","La Légende des siècles"]'::jsonb, 0, 'À la comédie divine succède la comédie humaine.', 2),
    ('8b90ac48-ffbc-5689-940f-936e9018b241'::uuid, '3225be99-cfa5-52f4-b4cd-3de075a672f9'::uuid, 'Quelles sont les trois grandes divisions de l’ensemble ?', 'mcq', '["Études de mœurs, Études philosophiques, Études analytiques","Romans, contes, essais","Paris, province, étranger","Passé, présent, avenir"]'::jsonb, 0, 'Les Études de mœurs forment la plus grande part.', 3),
    ('2e46aefe-5b30-53a8-a1e1-3982f38a345f'::uuid, '3225be99-cfa5-52f4-b4cd-3de075a672f9'::uuid, 'Qu’est-ce que le retour des personnages ?', 'mcq', '["Les mêmes personnages reparaissent d’un roman à l’autre","Les héros ressuscitent après leur mort","Les romans sont republiés dans un autre ordre","Les personnages racontent leur propre histoire"]'::jsonb, 0, 'Rastignac, Vautrin, Bianchon circulent d’un livre à l’autre.', 4),
    ('6b959818-7741-53c1-b6a1-a52f509d359b'::uuid, '3225be99-cfa5-52f4-b4cd-3de075a672f9'::uuid, 'Quelle ambition Balzac formule-t-il ?', 'mcq', '["Être le secrétaire de la société française, comme un naturaliste","Écrire une épopée nationale","Réformer la langue","Fonder une école littéraire"]'::jsonb, 0, 'Il veut classer les « espèces sociales » comme Buffon les espèces animales.', 5),
    ('d8b49bd5-a3bd-5cb1-9774-ae2fa9116f68'::uuid, '3225be99-cfa5-52f4-b4cd-3de075a672f9'::uuid, 'Le titre La Comédie humaine a été donné dès le premier roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est adopté en 1842, alors qu’une grande partie de l’œuvre était écrite.', 6),
    ('71a2fabc-05a3-5cc6-8f30-7c6c8e9665eb'::uuid, 'dcf48744-3e57-57ad-87bd-52122168030b'::uuid, 'Quand la nouvelle a-t-elle été publiée ?', 'mcq', '["En 1724, après la mort de l’autrice","En 1678, avec La Princesse de Clèves","En 1662","En 1700"]'::jsonb, 0, 'Elle a probablement été écrite avant La Princesse de Clèves.', 1),
    ('722dd21e-9979-5046-8d0a-675ee1504a3b'::uuid, 'dcf48744-3e57-57ad-87bd-52122168030b'::uuid, 'Que découvre la comtesse après sa liaison ?', 'mcq', '["Qu’elle est enceinte","Que son mari sait tout","Que le chevalier est marié","Qu’elle est ruinée"]'::jsonb, 0, 'Le chevalier meurt à la guerre peu après.', 2),
    ('5cdc08bc-e94b-5914-94bd-d7c58650dd95'::uuid, 'dcf48744-3e57-57ad-87bd-52122168030b'::uuid, 'Comment la comtesse avoue-t-elle sa faute ?', 'mcq', '["Par écrit, à son mari","Devant la cour","À un confesseur","Elle n’avoue pas"]'::jsonb, 0, 'L’aveu écrit est un motif propre à cette nouvelle.', 3),
    ('ebbb1677-3647-5943-b750-7e6d3af5a802'::uuid, 'dcf48744-3e57-57ad-87bd-52122168030b'::uuid, 'Quelle vengeance le comte choisit-il ?', 'mcq', '["L’abandonner à sa honte plutôt que la tuer","La tuer aussitôt","La répudier publiquement","La faire enfermer au couvent"]'::jsonb, 0, 'Il laisse même croire que l’enfant est le sien.', 4),
    ('08b13ccf-59cb-559a-97bc-28971825e7af'::uuid, 'dcf48744-3e57-57ad-87bd-52122168030b'::uuid, 'En quoi la nouvelle diffère-t-elle de La Princesse de Clèves ?', 'mcq', '["La passion y est consommée et l’aveu ne sauve rien","Elle finit bien","Elle se déroule au XVIIIe siècle","Elle est écrite en vers"]'::jsonb, 0, 'C’est la version sans espoir du même dilemme.', 5),
    ('8f0d7072-6c28-5843-9e42-a9e057af56c5'::uuid, 'dcf48744-3e57-57ad-87bd-52122168030b'::uuid, 'La comtesse survit à l’accouchement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle meurt en couches : la noirceur est complète.', 6),
    ('00c81c91-1223-53f4-ba71-6971bbb3565d'::uuid, '06db8fe5-dbff-567b-879d-127fb0c89c7f'::uuid, 'Où et quand se déroule le roman ?', 'mcq', '["À Shanghai, en 1927","À Pékin, en 1949","À Canton, en 1911","À Madrid, en 1936"]'::jsonb, 0, 'L’insurrection communiste y est écrasée par Tchang Kaï-chek.', 1),
    ('180116fd-4a70-58af-8090-24876196570c'::uuid, '06db8fe5-dbff-567b-879d-127fb0c89c7f'::uuid, 'Qui est Tchen ?', 'mcq', '["Un terroriste transformé par le meurtre, qui se fait sauter","Le chef du Kuomintang","Le père de Kyo","Un journaliste français"]'::jsonb, 0, 'Son parcours illustre la solitude du terrorisme.', 2),
    ('2c9b92da-17da-5ad0-906f-e8e2ffd8cb03'::uuid, '06db8fe5-dbff-567b-879d-127fb0c89c7f'::uuid, 'Quel geste rend Katow célèbre ?', 'mcq', '["Il donne son cyanure à deux jeunes compagnons","Il s’évade seul","Il négocie avec Tchang","Il tue un général"]'::jsonb, 0, 'La scène est l’une des plus fortes du roman.', 3),
    ('aa0fd01a-c23c-56a4-a110-2a48c67ede99'::uuid, '06db8fe5-dbff-567b-879d-127fb0c89c7f'::uuid, 'Quel personnage cause indirectement la mort de Kyo ?', 'mcq', '["Clappique, retenu au casino","Le vieux Gisors","Ferral","Hemmelrich"]'::jsonb, 0, 'Il oublie de transmettre l’avertissement.', 4),
    ('9530997d-6be8-5e07-baef-e5528c1fda16'::uuid, '06db8fe5-dbff-567b-879d-127fb0c89c7f'::uuid, 'Quel prix le roman a-t-il obtenu ?', 'mcq', '["Le prix Goncourt 1933","Le Renaudot","Le Femina","Le prix Nobel"]'::jsonb, 0, 'Il a fait de Malraux un écrivain majeur.', 5),
    ('a2add559-5edf-571e-a34d-8ca164ef1505'::uuid, '06db8fe5-dbff-567b-879d-127fb0c89c7f'::uuid, 'Le roman propose une seule réponse à la condition humaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Révolution, opium, érotisme, art : chaque personnage tente une réponse différente.', 6),
    ('b953e80b-be0e-5f58-9cd0-a2276574a4b9'::uuid, '0e36b033-f851-51f7-b6e9-e2b6a968804d'::uuid, 'Quel est le sujet de cette pièce ?', 'mcq', '["La discussion des critiques faites à L’École des femmes","Un mariage arrangé","Une querelle de voisinage","Un procès"]'::jsonb, 0, 'Molière répond par une pièce plutôt que par une préface.', 1),
    ('7e0adfdc-5802-5572-9602-ff231b7bd9d7'::uuid, '0e36b033-f851-51f7-b6e9-e2b6a968804d'::uuid, 'Quelle est la règle suprême selon Dorante ?', 'mcq', '["Plaire","Respecter les unités","Instruire","Imiter les Anciens"]'::jsonb, 0, '« La grande règle de toutes les règles n’est-elle pas de plaire ? »', 2),
    ('3d546258-9fcd-5c2e-9edd-a27c030d1bae'::uuid, '0e36b033-f851-51f7-b6e9-e2b6a968804d'::uuid, 'Quel personnage incarne la précieuse offusquée ?', 'mcq', '["Climène","Uranie","Élise","Dorante"]'::jsonb, 0, 'Elle attaque la pièce au nom de la bienséance.', 3),
    ('52d8d9a5-eecb-5331-a211-39919be85fd3'::uuid, '0e36b033-f851-51f7-b6e9-e2b6a968804d'::uuid, 'Que dit la pièce sur la comédie ?', 'mcq', '["Elle est plus difficile que la tragédie","Elle est un genre mineur","Elle doit corriger sans faire rire","Elle doit imiter la tragédie"]'::jsonb, 0, 'Il faut peindre d’après nature et faire rire les honnêtes gens.', 4),
    ('fe7dd80a-fe30-59bc-b6a3-b5c565e0a2eb'::uuid, '0e36b033-f851-51f7-b6e9-e2b6a968804d'::uuid, 'Quelle pièce prolonge la querelle la même année ?', 'mcq', '["L’Impromptu de Versailles","Le Misanthrope","Tartuffe","Les Précieuses ridicules"]'::jsonb, 0, 'Molière y met en scène sa propre troupe en répétition.', 5),
    ('fe590ce6-dfac-5cb4-aad6-5d2a0f2bb00b'::uuid, '0e36b033-f851-51f7-b6e9-e2b6a968804d'::uuid, 'La pièce comporte une intrigue et un dénouement classiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une conversation de salon : du théâtre qui parle du théâtre.', 6),
    ('485567e5-9d88-5dc0-b10a-3fd2053edfc8'::uuid, '8178d399-880e-52c9-ab1a-1bf58f9da134'::uuid, 'Sur quoi Saccard fait-il fortune ?', 'mcq', '["La spéculation sur les expropriations haussmanniennes","Le commerce colonial","Les chemins de fer","La banque agricole"]'::jsonb, 0, 'Il achète ce qu’il sait devoir être détruit et démoli.', 1),
    ('40e61130-6c0e-5aae-b93a-25ae314cc5f2'::uuid, '8178d399-880e-52c9-ab1a-1bf58f9da134'::uuid, 'Qui est Maxime ?', 'mcq', '["Le fils de Saccard, amant de Renée","Le frère de Renée","Un banquier rival","Le notaire de la famille"]'::jsonb, 0, 'La liaison est incestueuse au sens social du terme.', 2),
    ('bb18e04d-e339-55cb-ba38-25daffd4c74c'::uuid, '8178d399-880e-52c9-ab1a-1bf58f9da134'::uuid, 'Comment Saccard réagit-il en découvrant la liaison ?', 'mcq', '["Il en profite pour faire signer des papiers à sa femme","Il tue Maxime","Il divorce","Il quitte Paris"]'::jsonb, 0, 'Tout se convertit en argent chez lui, même le déshonneur.', 3),
    ('6c6d1f82-d25b-5cac-a2a6-c6ec6f523720'::uuid, '8178d399-880e-52c9-ab1a-1bf58f9da134'::uuid, 'Que signifie le titre du roman ?', 'mcq', '["Le partage des dépouilles après la chasse","La course des chevaux au bois","La chute d’un régime","Le nom d’un quartier de Paris"]'::jsonb, 0, 'Paris est la bête, l’Empire les chasseurs.', 4),
    ('a6e6ac99-272a-50f3-86b1-5ac5138d1c11'::uuid, '8178d399-880e-52c9-ab1a-1bf58f9da134'::uuid, 'Quel mythe antique Zola transpose-t-il ?', 'mcq', '["Phèdre, amoureuse de son beau-fils","Œdipe","Antigone","Médée"]'::jsonb, 0, 'Le mythe est transposé dans la spéculation immobilière.', 5),
    ('f3257346-368a-5664-8f66-69842eae3320'::uuid, '8178d399-880e-52c9-ab1a-1bf58f9da134'::uuid, 'Renée est un personnage actif et maître de son destin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Désœuvrée, manipulée et ruinée, elle meurt abandonnée.', 6)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 262 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 262 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
